import type {
  FieldValues,
  Path,
  PathValue,
  UseFormReturn,
} from 'react-hook-form';

export function applyReactHookFormValues<TValues extends FieldValues>(
  form: Pick<UseFormReturn<TValues>, 'setValue'>,
  values: Record<string, unknown>,
) {
  for (const [name, value] of Object.entries(values)) {
    const path = name as Path<TValues>;
    form.setValue(path, value as PathValue<TValues, typeof path>, {
      shouldDirty: true,
      shouldTouch: true,
      shouldValidate: true,
    });
  }
}

import { useApiClient } from '@nocobase/app-client';
import { useMemo } from 'react';

import { AIProvider, type AIProviderProps } from '../providers/ai-provider.js';
import { NocoBaseAIService } from '../services/index.js';
import { AIPageElementProvider } from './page-elements/page-element-provider.js';
import {
  AIToolRendererProvider,
  type AIToolRendererMap,
} from './tools/tool-renderer-provider.js';
import type { AIPageContextFailurePolicy } from './page-elements/page-element-store.js';

export type NocoBaseAIRootProviderProps = Omit<AIProviderProps, 'service'> & {
  /** Replaces the service built from the application's `ApiClient`. */
  service?: AIProviderProps['service'];
  toolRenderers?: AIToolRendererMap;
  contextFailurePolicy?: AIPageContextFailurePolicy;
};

export function NocoBaseAIRootProvider({
  children,
  toolRenderers,
  contextFailurePolicy,
  service: providedService,
  ...aiProviderProps
}: NocoBaseAIRootProviderProps) {
  const api = useApiClient();
  const service = useMemo(
    () => providedService ?? new NocoBaseAIService(api),
    [api, providedService],
  );
  return (
    <AIProvider {...aiProviderProps} service={service}>
      <AIToolRendererProvider renderers={toolRenderers}>
        <AIPageElementProvider contextFailurePolicy={contextFailurePolicy}>
          {children}
        </AIPageElementProvider>
      </AIToolRendererProvider>
    </AIProvider>
  );
}

import { useTranslation } from '@nocobase/i18n/client';
import { cn } from 'cn';
import { getAIEmployeeAvatar, type AIEmployee } from '../../providers/index.js';
import type { CSSProperties } from 'react';

export function AIEmployeeAvatar({
  employee,
  flip = false,
  className,
  style,
}: {
  employee?: AIEmployee;
  flip?: boolean;
  className?: string;
  style?: CSSProperties;
}) {
  const { t } = useTranslation('@nocobase/app-plugin-ai-employee');
  return (
    <span
      className={cn(
        'relative flex size-8 shrink-0 overflow-hidden rounded-full bg-transparent',
        className,
      )}
      style={style}
    >
      <img
        src={getAIEmployeeAvatar(employee?.avatar, { flip })}
        alt={employee?.nickname ?? t('chat.aiEmployee', 'AI employee')}
        className='size-full object-cover'
      />
    </span>
  );
}

import { useTranslation } from '@nocobase/i18n/client';
import { Button } from '../../shared/ui/button.js';
import { cn } from 'cn';
import type { AIChatAttachment } from '../../providers/index.js';
import { FileText, LoaderCircle, TriangleAlert, X } from 'lucide-react';

export function ChatAttachment({
  attachment,
  removable = false,
  onRemove,
}: {
  attachment: AIChatAttachment;
  removable?: boolean;
  onRemove?: () => void;
}) {
  const { t } = useTranslation('@nocobase/app-plugin-ai-employee');
  const preview = attachment.mimetype?.startsWith('image/')
    ? (attachment.preview ?? attachment.url)
    : undefined;
  const content = (
    <div
      className={cn(
        'relative flex h-14 min-w-0 items-center gap-2 rounded-lg border bg-background p-1.5 pr-2',
        attachment.status === 'error' && 'border-destructive/40',
      )}
    >
      <div className='flex size-10 shrink-0 items-center justify-center overflow-hidden rounded-md bg-muted'>
        {preview ? (
          <img src={preview} alt='' className='size-full object-cover' />
        ) : (
          <FileText className='size-4 text-muted-foreground' />
        )}
      </div>
      <div className='min-w-0 flex-1'>
        <div className='max-w-40 truncate text-xs font-medium'>
          {attachment.filename}
        </div>
        <div className='mt-0.5 flex items-center gap-1 text-[11px] text-muted-foreground'>
          {attachment.status === 'uploading' ? (
            <>
              <LoaderCircle className='size-3 animate-spin' />
              {t('chat.attachment.uploading', 'Uploading…')}
            </>
          ) : attachment.status === 'error' ? (
            <>
              <TriangleAlert className='size-3 text-destructive' />
              <span className='truncate text-destructive'>
                {attachment.error ??
                  t('chat.attachment.uploadFailed', 'Upload failed')}
              </span>
            </>
          ) : (
            formatFileSize(attachment.size, t('chat.attachment.file', 'File'))
          )}
        </div>
      </div>
      {removable ? (
        <Button
          type='button'
          variant='ghost'
          size='icon-xs'
          className='shrink-0 rounded-full'
          aria-label={t('chat.attachment.remove', 'Remove {{filename}}', {
            filename: attachment.filename,
          })}
          onClick={(event) => {
            event.preventDefault();
            event.stopPropagation();
            onRemove?.();
          }}
        >
          <X />
        </Button>
      ) : null}
    </div>
  );

  if (!removable && attachment.url) {
    return (
      <a
        href={attachment.url}
        target='_blank'
        rel='noreferrer'
        className='block rounded-lg outline-none focus-visible:ring-2 focus-visible:ring-ring'
      >
        {content}
      </a>
    );
  }
  return content;
}

function formatFileSize(size: number | undefined, fallback: string) {
  if (!size) return fallback;
  if (size < 1024) return `${size} B`;
  if (size < 1024 * 1024) return `${(size / 1024).toFixed(1)} KB`;
  return `${(size / 1024 / 1024).toFixed(1)} MB`;
}

import { useTranslation } from '@nocobase/i18n/client';
import { Button } from '../../shared/ui/button.js';
import { cn } from 'cn';
import { History, LoaderCircle } from 'lucide-react';
import { useState, type ReactNode } from 'react';
import {
  useAIChatBase,
  useAIChatStatus,
  type AIToolCallDecision,
} from '../../providers/index.js';
import { ChatComposer, type AIChatComposerAction } from './chat-composer.js';
import { AIChatHistoryDialog } from './chat-history-dialog.js';
import { ChatHeader } from './chat-header.js';

export type AIChatCompactProps = {
  className?: string;
  headerActions?: ReactNode;
  composerActions?: AIChatComposerAction[];
  showEmployeeSelector?: boolean;
  showModelSelector?: boolean;
  showUserPrompt?: boolean;
  enableAttachments?: boolean;
  enableWebSearch?: boolean;
  placeholder?: string;
  disclaimer?: ReactNode | false;
  onToolCallDecision?: (decision: AIToolCallDecision) => void | Promise<void>;
};

export function AIChatCompact({
  className,
  headerActions,
  composerActions,
  showEmployeeSelector = true,
  showModelSelector = true,
  showUserPrompt = true,
  enableAttachments = false,
  enableWebSearch = false,
  placeholder,
  disclaimer,
  onToolCallDecision,
}: AIChatCompactProps) {
  const { t } = useTranslation('@nocobase/app-plugin-ai-employee');
  const { currentEmployee } = useAIChatBase();
  const { status } = useAIChatStatus();
  const [historyOpen, setHistoryOpen] = useState(false);
  const busy = status === 'submitted' || status === 'streaming';

  return (
    <section
      className={cn(
        'flex min-h-0 w-full flex-col overflow-hidden rounded-xl border bg-card',
        className,
      )}
    >
      <ChatHeader
        showConversationToggle={false}
        showUserPrompt={showUserPrompt}
        actions={
          <>
            <Button
              variant='ghost'
              size='icon-sm'
              aria-label={t('chat.openHistory', 'Open message history')}
              onClick={() => setHistoryOpen(true)}
            >
              <History />
            </Button>
            {headerActions}
          </>
        }
      />
      {busy ? (
        <div className='flex items-center gap-2 border-b bg-muted/25 px-4 py-2 text-xs text-muted-foreground'>
          <LoaderCircle className='size-3.5 animate-spin' />
          {t('chat.employeeWorking', '{{name}} is working…', {
            name: currentEmployee.nickname,
          })}
        </div>
      ) : null}
      <ChatComposer
        actions={composerActions}
        showEmployeeSelector={showEmployeeSelector}
        showModelSelector={showModelSelector}
        enableAttachments={enableAttachments}
        enableWebSearch={enableWebSearch}
        placeholder={placeholder}
        disclaimer={disclaimer}
      />
      <AIChatHistoryDialog
        open={historyOpen}
        onOpenChange={setHistoryOpen}
        trigger={null}
        onToolCallDecision={onToolCallDecision}
      />
    </section>
  );
}

import { useTranslation } from '@nocobase/i18n/client';
import {
  InputGroup,
  InputGroupAddon,
  InputGroupButton,
  InputGroupTextarea,
} from '../../shared/ui/input-group.js';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '../../shared/ui/select.js';
import {
  HoverCard,
  HoverCardContent,
  HoverCardTrigger,
} from '../../shared/ui/hover-card.js';
import {
  getAIModelKey,
  useAIChatBase,
  useAIChatStatus,
  type AIEmployee,
} from '../../providers/index.js';
import { cn } from 'cn';
import { ArrowUp, Globe2, Paperclip, Pencil, Square, X } from 'lucide-react';
import { useEffect, useRef, useState, type ReactNode } from 'react';
import { AIEmployeeAvatar } from './ai-employee-avatar.js';
import { WorkContextChip } from './work-context-chip.js';
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from '../../shared/ui/tooltip.js';
import { AIModelSelectOptions } from './model-select-options.js';
import { ChatAttachment } from './chat-attachment.js';

export type AIChatComposerAction = {
  key: string;
  label: string;
  icon?: ReactNode;
  active?: boolean;
  disabled?: boolean;
  showLabel?: boolean;
  onClick?: () => void;
};

export function ChatComposer({
  actions = [],
  showEmployeeSelector = true,
  showModelSelector = true,
  enableAttachments = false,
  enableWebSearch = false,
  attachmentActionIndex = 0,
  placeholder,
  disclaimer,
}: {
  actions?: AIChatComposerAction[];
  showEmployeeSelector?: boolean;
  showModelSelector?: boolean;
  enableAttachments?: boolean;
  enableWebSearch?: boolean;
  attachmentActionIndex?: number;
  placeholder?: string;
  disclaimer?: ReactNode | false;
}) {
  const { t } = useTranslation('@nocobase/app-plugin-ai-employee');
  const {
    draft,
    setDraft,
    send,
    stop,
    models,
    employees,
    currentEmployee,
    currentModel,
    canSend,
    selectModel,
    selectEmployee,
    composerFocusRequest,
    attachments,
    uploadingAttachments,
    uploadFiles,
    removeAttachment,
    webSearch,
    setWebSearch,
    workContext,
    removeWorkContext,
    editingMessageId,
    cancelEditingMessage,
  } = useAIChatBase();
  const { status } = useAIChatStatus();
  const busy = status === 'submitted' || status === 'streaming';
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [employeeSelectOpen, setEmployeeSelectOpen] = useState(false);
  const [previewedEmployee, setPreviewedEmployee] = useState<string>();
  const visibleEmployees = employees.filter(
    (employee) =>
      (employee.category === undefined || employee.category === 'business') &&
      employee.deprecated !== true,
  );
  const normalizedAttachmentActionIndex = Math.max(
    0,
    Math.min(attachmentActionIndex, actions.length),
  );
  const resolvedPlaceholder =
    placeholder ?? t('chat.composer.placeholder', 'Message your AI employee…');
  const resolvedDisclaimer =
    disclaimer === undefined
      ? t(
          'chat.composer.disclaimer',
          'AI can make mistakes. Review important changes before publishing.',
        )
      : disclaimer;
  const canSearchWeb = currentModel.supportWebSearch === true;
  const webSearchAction: AIChatComposerAction = {
    key: 'web-search',
    label: canSearchWeb
      ? t('actions.webSearch', 'Web search')
      : t(
          'actions.webSearchUnsupported',
          'Web search is not supported by this model',
        ),
    icon: <Globe2 />,
    active: webSearch,
    disabled: !canSearchWeb,
    onClick: () => setWebSearch(!webSearch),
  };
  const renderAction = (action: AIChatComposerAction) => (
    <Tooltip key={action.key}>
      <TooltipTrigger
        render={
          <InputGroupButton
            size={action.showLabel ? 'xs' : 'icon-sm'}
            variant={action.active ? 'secondary' : 'ghost'}
            className={cn(
              'h-7 shrink-0',
              action.showLabel ? 'px-2' : 'w-7 p-0',
            )}
            disabled={action.disabled}
            aria-label={action.label}
            aria-pressed={action.active}
            onClick={action.onClick}
          />
        }
      >
        {action.icon}
        {action.showLabel ? action.label : null}
      </TooltipTrigger>
      <TooltipContent>{action.label}</TooltipContent>
    </Tooltip>
  );

  // A model that cannot search leaves the toggle disabled, so it must not stay
  // on from a model that could.
  useEffect(() => {
    if (enableWebSearch && webSearch && !canSearchWeb) setWebSearch(false);
  }, [canSearchWeb, enableWebSearch, setWebSearch, webSearch]);

  useEffect(() => {
    if (composerFocusRequest === 0) return;
    const frame = requestAnimationFrame(() => {
      const textarea = textareaRef.current;
      if (!textarea) return;
      textarea.focus();
      const end = textarea.value.length;
      textarea.setSelectionRange(end, end);
    });
    return () => cancelAnimationFrame(frame);
  }, [composerFocusRequest]);

  return (
    <footer className='shrink-0 bg-card'>
      <div className='mx-4 mt-2'>
        <InputGroup className='rounded-xl bg-background shadow-[0_6px_24px_rgba(0,0,0,0.06)] has-disabled:bg-background has-disabled:opacity-100 focus-within:shadow-[0_8px_28px_rgba(0,0,0,0.08)] dark:has-disabled:bg-background'>
          {editingMessageId ? (
            <InputGroupAddon
              align='block-start'
              className='justify-between border-b px-3 py-2 text-xs'
            >
              <span className='flex items-center gap-2 text-foreground'>
                <Pencil className='size-3.5' />
                {t('chat.composer.editing', 'Editing message')}
              </span>
              <InputGroupButton
                size='icon-xs'
                aria-label={t('chat.composer.cancelEditing', 'Cancel editing')}
                onClick={cancelEditingMessage}
              >
                <X />
              </InputGroupButton>
            </InputGroupAddon>
          ) : null}
          {workContext.length ? (
            <InputGroupAddon
              align='block-start'
              className='flex-wrap justify-start gap-1.5 px-3 pt-2'
            >
              {workContext.map((item, index) => (
                <WorkContextChip
                  key={`${item.type}:${item.id ?? item.title ?? index}`}
                  item={item}
                  onRemove={() => removeWorkContext(item)}
                />
              ))}
            </InputGroupAddon>
          ) : null}
          {enableAttachments && attachments.length ? (
            <InputGroupAddon
              align='block-start'
              className='flex-wrap justify-start gap-1.5 px-3 pt-2'
            >
              {attachments.map((attachment) => (
                <ChatAttachment
                  key={attachment.uid}
                  attachment={attachment}
                  removable
                  onRemove={() => removeAttachment(attachment.uid)}
                />
              ))}
            </InputGroupAddon>
          ) : null}
          <InputGroupTextarea
            ref={textareaRef}
            value={draft}
            rows={2}
            placeholder={resolvedPlaceholder}
            className='max-h-44 min-h-16 px-3 pt-3 text-sm'
            onChange={(event) => setDraft(event.target.value)}
            onPaste={(event) => {
              if (!enableAttachments || !canSend) return;
              const files = Array.from(event.clipboardData.items)
                .filter((item) => item.kind === 'file')
                .map((item) => item.getAsFile())
                .filter((file): file is File => file !== null);
              if (!files.length) return;
              event.preventDefault();
              void uploadFiles(files);
            }}
            onKeyDown={(event) => {
              if (event.nativeEvent.isComposing) return;
              if (event.key === 'Enter' && !event.shiftKey) {
                event.preventDefault();
                void send();
              }
            }}
          />
          <InputGroupAddon
            align='block-end'
            className='justify-between px-2.5 pb-2'
          >
            <div className='flex min-w-0 items-center gap-2 overflow-x-auto [scrollbar-width:none]'>
              {actions
                .slice(0, normalizedAttachmentActionIndex)
                .map(renderAction)}
              {enableAttachments ? (
                <Tooltip>
                  <TooltipTrigger
                    render={
                      <InputGroupButton
                        size='icon-sm'
                        variant='ghost'
                        className='h-7 w-7 shrink-0 p-0'
                        aria-label={t(
                          'chat.composer.uploadFiles',
                          'Upload files',
                        )}
                        onClick={() => fileInputRef.current?.click()}
                      />
                    }
                  >
                    <Paperclip />
                  </TooltipTrigger>
                  <TooltipContent>
                    {t('chat.composer.uploadFiles', 'Upload files')}
                  </TooltipContent>
                </Tooltip>
              ) : null}
              {enableWebSearch ? renderAction(webSearchAction) : null}
              {actions.slice(normalizedAttachmentActionIndex).map(renderAction)}
              {showEmployeeSelector ? (
                <Select
                  open={employeeSelectOpen}
                  value={currentEmployee.username}
                  onOpenChange={(open) => {
                    setEmployeeSelectOpen(open);
                    if (!open) setPreviewedEmployee(undefined);
                  }}
                  onValueChange={(value) => {
                    setPreviewedEmployee(undefined);
                    if (value) selectEmployee(value);
                  }}
                >
                  <SelectTrigger
                    size='sm'
                    className='max-w-36 shrink-0 border-0 bg-muted/60 px-1.5 shadow-none'
                  >
                    <SelectValue>
                      <span className='flex min-w-0 items-center gap-1.5'>
                        <AIEmployeeAvatar
                          employee={currentEmployee}
                          className='size-5'
                        />
                        <span className='truncate'>
                          {currentEmployee.nickname}
                        </span>
                      </span>
                    </SelectValue>
                  </SelectTrigger>
                  <SelectContent side='top' className='max-h-[400px] min-w-72'>
                    {visibleEmployees.map((employee) => (
                      <SelectItem
                        key={employee.username}
                        value={employee.username}
                        className='py-1.5'
                      >
                        <HoverCard
                          open={
                            employeeSelectOpen &&
                            previewedEmployee === employee.username
                          }
                          onOpenChange={(open) => {
                            if (!employeeSelectOpen) return;
                            setPreviewedEmployee(
                              open ? employee.username : undefined,
                            );
                          }}
                        >
                          <HoverCardTrigger
                            delay={250}
                            closeDelay={100}
                            render={
                              <span className='flex min-w-0 flex-1 items-center gap-2' />
                            }
                          >
                            <AIEmployeeAvatar
                              employee={employee}
                              className='size-9'
                            />
                            <span className='min-w-0'>
                              <span className='block font-medium'>
                                {employee.nickname}
                              </span>
                              {employee.position ? (
                                <span className='block truncate text-xs text-muted-foreground'>
                                  {employee.position}
                                </span>
                              ) : null}
                            </span>
                          </HoverCardTrigger>
                          <HoverCardContent
                            side='left'
                            align='start'
                            sideOffset={8}
                            className='w-65 p-3 data-closed:hidden'
                          >
                            <AIEmployeeProfile employee={employee} />
                          </HoverCardContent>
                        </HoverCard>
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              ) : null}
              {showModelSelector ? (
                <Select
                  value={getAIModelKey(currentModel)}
                  onValueChange={(value) => value && selectModel(value)}
                >
                  <SelectTrigger
                    size='sm'
                    title={currentModel.label}
                    className='w-28 max-w-28 shrink-0 border-0 bg-muted/60 px-1.5 shadow-none'
                  >
                    <SelectValue className='min-w-0 overflow-hidden'>
                      <span className='block min-w-0 truncate'>
                        {currentModel.label}
                      </span>
                    </SelectValue>
                  </SelectTrigger>
                  <SelectContent side='top' className='max-h-[400px] min-w-56'>
                    <AIModelSelectOptions models={models} />
                  </SelectContent>
                </Select>
              ) : null}
            </div>
            {busy ? (
              <InputGroupButton
                size='icon-sm'
                variant='default'
                className='rounded-lg'
                aria-label={t('chat.composer.stop', 'Stop generating')}
                onClick={() => void stop()}
              >
                <Square className='size-3 fill-current' />
              </InputGroupButton>
            ) : (
              <InputGroupButton
                size='icon-sm'
                variant='default'
                className='rounded-lg'
                aria-label={t('chat.composer.send', 'Send message')}
                disabled={
                  !canSend ||
                  uploadingAttachments ||
                  (!draft.trim() &&
                    !attachments.some(
                      (attachment) => attachment.status === 'done',
                    ) &&
                    !workContext.length)
                }
                onClick={() => void send()}
              >
                <ArrowUp />
              </InputGroupButton>
            )}
          </InputGroupAddon>
        </InputGroup>
        {enableAttachments ? (
          <input
            ref={fileInputRef}
            type='file'
            multiple
            className='hidden'
            tabIndex={-1}
            aria-hidden='true'
            onChange={(event) => {
              const files = Array.from(event.target.files ?? []);
              if (files.length) void uploadFiles(files);
              event.target.value = '';
            }}
          />
        ) : null}
      </div>
      {resolvedDisclaimer !== false ? (
        <p className='my-2.5 px-4 text-center text-[11px] text-muted-foreground'>
          {resolvedDisclaimer}
        </p>
      ) : (
        <div className='h-2' />
      )}
    </footer>
  );
}

function AIEmployeeProfile({ employee }: { employee: AIEmployee }) {
  const description = employee.bio ?? employee.description;

  return (
    <div>
      <div className='flex items-center gap-3'>
        <AIEmployeeAvatar employee={employee} className='size-10' />
        <div className='min-w-0'>
          <div className='truncate text-sm font-medium'>
            {employee.nickname}
          </div>
          {employee.position ? (
            <div className='truncate text-xs text-muted-foreground'>
              {employee.position}
            </div>
          ) : null}
        </div>
      </div>
      {description ? (
        <p className='mt-3 border-t pt-3 text-xs leading-5 text-muted-foreground'>
          {description}
        </p>
      ) : null}
    </div>
  );
}

import { useTranslation } from '@nocobase/i18n/client';
import { Button } from '../../shared/ui/button.js';
import { useAIChatBase } from '../../providers/index.js';
import { ArrowUpRight, Send, TextCursorInput } from 'lucide-react';
import { AIEmployeeAvatar } from './ai-employee-avatar.js';
import { withStableKeys } from '../../shared/keys.js';

export function ChatEmptyState() {
  const { t } = useTranslation('@nocobase/app-plugin-ai-employee');
  const { currentEmployee, availableTasks, runTask } = useAIChatBase();

  return (
    <div className='flex min-h-full items-center justify-center px-6 py-12'>
      <div className='w-full max-w-sm text-center'>
        <AIEmployeeAvatar
          employee={currentEmployee}
          className='mx-auto size-12'
        />
        <p className='mx-auto mt-4 max-w-xs text-sm leading-6 text-muted-foreground'>
          {currentEmployee.greeting ??
            t('chat.defaultGreeting', 'Hi, I’m {{name}}. How can I help?', {
              name: currentEmployee.nickname,
            })}
        </p>
        {availableTasks.length ? (
          <div className='mt-6 grid gap-2 text-left'>
            {withStableKeys(
              availableTasks,
              (task) => task.title ?? task.message?.user ?? 'task',
            ).map(({ key, item: task }, index) => {
              const Icon = task.autoSend ? Send : TextCursorInput;
              return (
                <Button
                  key={key}
                  variant='outline'
                  className='h-auto justify-start gap-3 whitespace-normal px-3 py-3 text-left font-normal'
                  onClick={() => runTask(task)}
                >
                  <Icon className='size-4 text-muted-foreground' />
                  <span className='min-w-0 flex-1'>
                    <span className='block'>
                      {task.title ??
                        task.message?.user ??
                        t('chat.task.fallback', 'Task {{number}}', {
                          number: index + 1,
                        })}
                    </span>
                    <span className='mt-0.5 block text-[11px] text-muted-foreground'>
                      {task.autoSend
                        ? t('chat.task.automatic', 'Send automatically')
                        : t(
                            'chat.task.fillComposer',
                            'Fill the composer before sending',
                          )}
                    </span>
                  </span>
                  <ArrowUpRight className='size-3.5 text-muted-foreground' />
                </Button>
              );
            })}
          </div>
        ) : null}
      </div>
    </div>
  );
}

