import { useTranslation } from '@nocobase/i18n/client';
import { Button } from '../../shared/ui/button.js';
import {
  type AIChatMessage as AIChatMessageType,
  type AIToolCallDecision,
} from '../../providers/index.js';
import { Check, Copy, Pencil, RefreshCcw } from 'lucide-react';
import { memo, useState } from 'react';
import { MarkdownMessage } from './markdown-message.js';
import { ReasoningPanel } from './reasoning-panel.js';
import { ToolCallCard } from './tool-call-card.js';
import { getToolCallName, isToolCallPart } from './tool-call-utils.js';
import { ChatAttachment } from './chat-attachment.js';
import { useAIToolRenderer } from '../tools/tool-renderer-context.js';
import { SubAgentConversation } from './sub-agent-conversation.js';
import { WorkContextChip } from './work-context-chip.js';
import { withStableKeys } from '../../shared/keys.js';

const getPartKey = (part: AIChatMessageType['parts'][number]) => {
  if (part.type === 'data-subAgent') return part.id ?? part.data.sessionId;
  if (isToolCallPart(part)) return part.toolCallId;
  return part.type;
};

type ChatMessageProps = {
  message: AIChatMessageType;
  onToolCallDecision?: (decision: AIToolCallDecision) => void | Promise<void>;
  showActions?: boolean;
  readOnly?: boolean;
  status?: 'submitted' | 'streaming' | 'ready' | 'error';
  retryMessage?: (message: AIChatMessageType) => Promise<void>;
  decideToolCall?: (decision: AIToolCallDecision) => Promise<void>;
  startEditingMessage?: (message: AIChatMessageType) => Promise<void>;
  focusComposer?: () => void;
};

function ChatMessageComponent({
  message,
  onToolCallDecision,
  showActions = true,
  readOnly = false,
  status = 'ready',
  retryMessage,
  decideToolCall,
  startEditingMessage,
  focusComposer,
}: ChatMessageProps) {
  const { t } = useTranslation('@nocobase/app-plugin-ai-employee');
  const interactionPending = status === 'streaming' || status === 'submitted';
  const [copied, setCopied] = useState(false);
  const copyText = async () => {
    await navigator.clipboard.writeText(text);
    setCopied(true);
    window.setTimeout(() => setCopied(false), 1200);
  };
  const isUser = message.role === 'user';
  const text = message.parts
    .filter((part) => part.type === 'text')
    .map((part) => part.text)
    .join('\n');
  const toolCalls = message.parts.filter(isToolCallPart);
  const singleToolCall = toolCalls.length === 1 ? toolCalls[0] : undefined;
  const singleToolRenderer = useAIToolRenderer(
    singleToolCall ? getToolCallName(singleToolCall) : '',
  );
  const useInlineToolActions =
    !text && Boolean(singleToolCall) && !singleToolRenderer;
  const assistantParts = message.parts.filter(
    (part) =>
      part.type === 'text' ||
      part.type === 'reasoning' ||
      part.type === 'data-subAgent' ||
      isToolCallPart(part),
  );
  const showGenerating = !assistantParts.length && interactionPending;
  const attachments = message.metadata?.attachments ?? [];
  const workContext = message.metadata?.workContext ?? [];
  if (isUser) {
    return (
      <article className='group/message flex min-w-0 max-w-full flex-col items-end px-4 py-2 sm:px-5'>
        <div className='flex min-w-0 max-w-[80%] flex-col items-end'>
          {workContext.length ? (
            <div className='mb-1.5 flex max-w-full flex-wrap justify-end gap-1.5'>
              {workContext.map((item, index) => (
                <WorkContextChip
                  key={`${item.type}:${item.id ?? item.title ?? index}`}
                  item={item}
                  className='bg-background'
                />
              ))}
            </div>
          ) : null}
          {attachments.length ? (
            <div className='mb-1.5 flex max-w-full flex-wrap justify-end gap-1.5'>
              {attachments.map((attachment) => (
                <ChatAttachment key={attachment.uid} attachment={attachment} />
              ))}
            </div>
          ) : null}
          {text ? (
            <div className='min-w-0 max-w-full rounded-2xl rounded-br-md bg-secondary px-4 py-2.5 text-sm leading-6 text-secondary-foreground'>
              <div className='whitespace-pre-wrap [overflow-wrap:anywhere]'>
                {text}
              </div>
            </div>
          ) : null}
        </div>
        {showActions && !readOnly ? (
          <div className='pointer-events-none mt-1 flex h-6 items-center gap-1 opacity-0 transition-opacity group-hover/message:pointer-events-auto group-hover/message:opacity-100 focus-within:pointer-events-auto focus-within:opacity-100'>
            <Button
              variant='ghost'
              size='icon-xs'
              aria-label={t('chat.message.edit', 'Edit message')}
              disabled={interactionPending || !startEditingMessage}
              onClick={() => void startEditingMessage?.(message)}
            >
              <Pencil />
            </Button>
            {text ? (
              <Button
                variant='ghost'
                size='icon-xs'
                aria-label={t('chat.message.copy', 'Copy message')}
                onClick={() => void copyText()}
              >
                {copied ? <Check /> : <Copy />}
              </Button>
            ) : null}
          </div>
        ) : null}
      </article>
    );
  }

  const messageActions = (
    <>
      {text ? (
        <Button
          variant='ghost'
          size='icon-xs'
          aria-label={t('chat.message.copyResponse', 'Copy response')}
          onClick={() => void copyText()}
        >
          {copied ? <Check /> : <Copy />}
        </Button>
      ) : null}
      <Button
        variant='ghost'
        size='icon-xs'
        aria-label={t('chat.message.retry', 'Retry response')}
        disabled={interactionPending || !retryMessage}
        onClick={() => void retryMessage?.(message)}
      >
        <RefreshCcw />
      </Button>
    </>
  );

  return (
    <article className='group/message min-w-0 max-w-full px-4 py-2 sm:px-5'>
      <div className='min-w-0 space-y-4'>
        {withStableKeys(assistantParts, getPartKey).map(
          ({ key, item: part }) => {
            if (part.type === 'reasoning') {
              return (
                <ReasoningPanel
                  key={key}
                  streaming={part.state === 'streaming'}
                >
                  {part.text}
                </ReasoningPanel>
              );
            }
            if (part.type === 'text') {
              return (
                <div
                  key={key}
                  className='ai-markdown min-w-0 max-w-full [overflow-wrap:anywhere] text-sm leading-6 text-foreground'
                >
                  <MarkdownMessage>{part.text}</MarkdownMessage>
                </div>
              );
            }
            if (part.type === 'data-subAgent') {
              return (
                <SubAgentConversation
                  key={key}
                  conversation={part.data}
                  readOnly={readOnly}
                  onToolCallDecision={onToolCallDecision}
                  status={status}
                  decideToolCall={decideToolCall}
                  focusComposer={focusComposer}
                />
              );
            }
            if (!isToolCallPart(part)) return null;
            return (
              <ToolCallCard
                key={key}
                part={part}
                approval={message.metadata?.toolApprovals?.[part.toolCallId]}
                disabled={interactionPending}
                readOnly={readOnly}
                onRevise={focusComposer}
                inlineActions={
                  showActions &&
                  !readOnly &&
                  useInlineToolActions &&
                  part === singleToolCall
                    ? messageActions
                    : undefined
                }
                onDecision={async (decision, input) => {
                  if (readOnly) return;
                  const toolDecision = {
                    messageId: message.id,
                    toolCallId: part.toolCallId,
                    toolName: getToolCallName(part),
                    decision,
                    input,
                  } satisfies AIToolCallDecision;
                  await decideToolCall?.(toolDecision);
                  try {
                    await onToolCallDecision?.(toolDecision);
                  } catch (error) {
                    console.error('Tool-call decision callback failed', error);
                  }
                }}
              />
            );
          },
        )}
        {showGenerating ? (
          <div className='min-h-6 text-sm leading-6 text-foreground'>
            <span
              className='inline-flex gap-1 py-2'
              aria-label={t('chat.message.generating', 'Generating response')}
            >
              <span className='size-1.5 animate-pulse rounded-full bg-muted-foreground/70' />
              <span className='size-1.5 animate-pulse rounded-full bg-muted-foreground/70 [animation-delay:120ms]' />
              <span className='size-1.5 animate-pulse rounded-full bg-muted-foreground/70 [animation-delay:240ms]' />
            </span>
          </div>
        ) : null}
      </div>
      {showActions &&
      !readOnly &&
      (text || (toolCalls.length && !useInlineToolActions)) ? (
        <div className='pointer-events-none mt-1 flex h-6 items-center gap-1 opacity-0 transition-opacity group-hover/message:pointer-events-auto group-hover/message:opacity-100 focus-within:pointer-events-auto focus-within:opacity-100'>
          {messageActions}
        </div>
      ) : null}
    </article>
  );
}

export const ChatMessage = memo(
  ChatMessageComponent,
  (previous, next) =>
    previous.message === next.message &&
    previous.status === next.status &&
    previous.showActions === next.showActions &&
    previous.readOnly === next.readOnly &&
    previous.onToolCallDecision === next.onToolCallDecision &&
    previous.retryMessage === next.retryMessage &&
    previous.decideToolCall === next.decideToolCall &&
    previous.startEditingMessage === next.startEditingMessage &&
    previous.focusComposer === next.focusComposer,
);

import { useTranslation } from '@nocobase/i18n/client';
import { Button } from '../../shared/ui/button.js';
import { LoadingState } from '../../shared/loading-state.js';
import {
  useAIChatBase,
  useAIChatMessages,
  useAIChatStatus,
  type AIChatMessage,
  type AIToolCallDecision,
} from '../../providers/index.js';
import { cn } from 'cn';
import { ArrowDown } from 'lucide-react';
import {
  useCallback,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  type ReactNode,
} from 'react';
import { ChatEmptyState } from './chat-empty-state.js';
import { ChatMessage } from './chat-message.js';

export function ChatMessages({
  onToolCallDecision,
}: {
  onToolCallDecision?: (decision: AIToolCallDecision) => void | Promise<void>;
}) {
  const { messages } = useAIChatMessages();
  const { status, error } = useAIChatStatus();
  const {
    messagesLoading,
    historyError,
    interactionError,
    retryMessage,
    decideToolCall,
    startEditingMessage,
    focusComposer,
  } = useAIChatBase();

  return (
    <AIChatMessageList
      messages={messages}
      status={status}
      loading={messagesLoading}
      error={error}
      historyError={historyError}
      interactionError={interactionError}
      onToolCallDecision={onToolCallDecision}
      retryMessage={retryMessage}
      decideToolCall={decideToolCall}
      startEditingMessage={startEditingMessage}
      focusComposer={focusComposer}
    />
  );
}

export type AIChatMessageListProps = {
  messages: AIChatMessage[];
  status?: 'submitted' | 'streaming' | 'ready' | 'error';
  loading?: boolean;
  error?: Error | null;
  historyError?: Error | null;
  interactionError?: Error | null;
  emptyState?: ReactNode;
  /** Content such as a load-earlier control, rendered inside the scrolling history. */
  historyHeader?: ReactNode;
  className?: string;
  onToolCallDecision?: (decision: AIToolCallDecision) => void | Promise<void>;
  /** Hiding message actions also disables interactive tool and subagent rendering. */
  showMessageActions?: boolean;
  /** Render history without mounting interactive tool renderers or task controls. */
  readOnly?: boolean;
  retryMessage?: (message: AIChatMessage) => Promise<void>;
  decideToolCall?: (decision: AIToolCallDecision) => Promise<void>;
  startEditingMessage?: (message: AIChatMessage) => Promise<void>;
  focusComposer?: () => void;
};

type ScrollSnapshot = {
  first?: Element;
  last?: Element;
  anchor?: Element;
  anchorTop: number;
  scrollTop: number;
  scrollHeight: number;
};

export function AIChatMessageList({
  messages,
  status = 'ready',
  loading = false,
  error,
  historyError,
  interactionError,
  emptyState,
  historyHeader,
  className,
  onToolCallDecision,
  showMessageActions = true,
  readOnly = false,
  retryMessage,
  decideToolCall,
  startEditingMessage,
  focusComposer,
}: AIChatMessageListProps) {
  const { t } = useTranslation('@nocobase/app-plugin-ai-employee');
  const viewportRef = useRef<HTMLDivElement>(null);
  const contentRef = useRef<HTMLDivElement>(null);
  const messageListRef = useRef<HTMLDivElement>(null);
  const snapshotRef = useRef<ScrollSnapshot | null>(null);
  const atBottomRef = useRef(true);
  const [atBottom, setAtBottom] = useState(true);
  const hasContent = Boolean(
    messages.length ||
    historyHeader ||
    emptyState ||
    error ||
    historyError ||
    interactionError ||
    (!readOnly && showMessageActions),
  );

  const capturePosition = useCallback(() => {
    const viewport = viewportRef.current;
    if (!viewport) return;
    const rows = Array.from(messageListRef.current?.children ?? []);
    const viewportTop = viewport.getBoundingClientRect().top;
    const anchor = rows.find(
      (row) => row.getBoundingClientRect().bottom > viewportTop,
    );
    snapshotRef.current = {
      first: rows[0],
      last: rows.at(-1),
      anchor,
      anchorTop: anchor ? anchor.getBoundingClientRect().top - viewportTop : 0,
      scrollTop: viewport.scrollTop,
      scrollHeight: viewport.scrollHeight,
    };
  }, []);

  const updateAtBottom = useCallback(() => {
    const viewport = viewportRef.current;
    if (!viewport) return;
    const next =
      viewport.scrollHeight - viewport.scrollTop - viewport.clientHeight < 48;
    atBottomRef.current = next;
    setAtBottom(next);
  }, []);

  const scrollToBottom = () => {
    const viewport = viewportRef.current;
    if (!viewport) return;
    const reducedMotion = window.matchMedia?.(
      '(prefers-reduced-motion: reduce)',
    ).matches;
    viewport.focus({ preventScroll: true });
    viewport.scrollTo({
      top: Math.max(0, viewport.scrollHeight - viewport.clientHeight),
      behavior: reducedMotion ? 'auto' : 'smooth',
    });
  };

  const restorePosition = useCallback(() => {
    const viewport = viewportRef.current;
    if (!viewport) return;
    const previous = snapshotRef.current;
    const rows = messageListRef.current?.children;
    const first = rows?.[0];
    const isNewHistory =
      first &&
      (!previous?.first ||
        (!viewport.contains(previous.first) &&
          !viewport.contains(previous.last ?? null)));
    const prepended =
      previous?.first &&
      first !== previous.first &&
      viewport.contains(previous.first);

    // A prepend must take precedence over tail-follow, even for a short history
    // that previously fitted in the viewport. Anchor a row, not total height:
    // the tail can stream and the history header can change in the same commit.
    if (isNewHistory || (atBottomRef.current && !prepended)) {
      viewport.scrollTop = Math.max(
        0,
        viewport.scrollHeight - viewport.clientHeight,
      );
    } else if (previous) {
      if (previous.anchor && viewport.contains(previous.anchor)) {
        viewport.scrollTop +=
          previous.anchor.getBoundingClientRect().top -
          viewport.getBoundingClientRect().top -
          previous.anchorTop;
      } else {
        viewport.scrollTop =
          previous.scrollTop +
          (prepended ? viewport.scrollHeight - previous.scrollHeight : 0);
      }
    }
    updateAtBottom();
    capturePosition();
  }, [capturePosition, updateAtBottom]);

  // Restore content changes before paint, not the state render caused by a
  // scroll event: merely approaching the bottom must not snap the reader there.
  useLayoutEffect(() => {
    restorePosition();
  }, [
    messages,
    status,
    loading,
    historyHeader,
    emptyState,
    error,
    historyError,
    interactionError,
    readOnly,
    showMessageActions,
    restorePosition,
  ]);

  useEffect(() => {
    const viewport = viewportRef.current;
    const content = contentRef.current;
    if (!viewport || typeof ResizeObserver === 'undefined') return;

    // Observe content too: images, tools and streamed Markdown can grow without
    // changing the viewport size or causing this component to render.
    const observer = new ResizeObserver(() => restorePosition());
    observer.observe(viewport);
    if (content) observer.observe(content);
    return () => observer.disconnect();
  }, [loading, hasContent, restorePosition]);

  return (
    <div
      className={cn(
        'relative min-h-0 min-w-0 flex-1 overflow-hidden bg-background',
        className,
      )}
    >
      <div
        ref={viewportRef}
        role='log'
        aria-label={t('chat.messageHistory', 'Message history')}
        aria-live='polite'
        tabIndex={0}
        className='absolute inset-0 overflow-x-hidden overflow-y-auto overscroll-contain scroll-auto [overflow-anchor:none] focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-ring'
        onScroll={() => {
          updateAtBottom();
          capturePosition();
        }}
      >
        {loading ? (
          <LoadingState className='h-full' />
        ) : hasContent ? (
          <div ref={contentRef} className='flex min-h-full flex-col'>
            {historyHeader}
            {messages.length ? (
              <div
                ref={messageListRef}
                className='mx-auto min-w-0 w-full max-w-3xl py-2'
              >
                {messages.map((message) => (
                  <div key={message.id} data-chat-message-id={message.id}>
                    <ChatMessage
                      message={message}
                      onToolCallDecision={onToolCallDecision}
                      showActions={showMessageActions && !readOnly}
                      readOnly={readOnly || !showMessageActions}
                      status={status}
                      retryMessage={retryMessage}
                      decideToolCall={decideToolCall}
                      startEditingMessage={startEditingMessage}
                      focusComposer={focusComposer}
                    />
                  </div>
                ))}
              </div>
            ) : (
              (emptyState ??
              (readOnly || !showMessageActions ? null : (
                <div className='flex flex-1 flex-col justify-center'>
                  <ChatEmptyState />
                </div>
              )))
            )}
            {error ? (
              <div
                role='alert'
                className='mx-5 my-3 rounded-lg border border-destructive/25 bg-destructive/5 px-3 py-2 text-sm text-destructive'
              >
                {error.message}
              </div>
            ) : null}
            {historyError ? (
              <div
                role='alert'
                className='mx-5 my-3 rounded-lg border border-destructive/25 bg-destructive/5 px-3 py-2 text-sm text-destructive'
              >
                {historyError.message}
              </div>
            ) : null}
            {interactionError ? (
              <div
                role='alert'
                className='mx-5 my-3 rounded-lg border border-destructive/25 bg-destructive/5 px-3 py-2 text-sm text-destructive'
              >
                {interactionError.message}
              </div>
            ) : null}
          </div>
        ) : null}
      </div>
      {!atBottom ? (
        <Button
          size='icon-sm'
          variant='outline'
          className='absolute bottom-3 left-1/2 z-10 -translate-x-1/2 rounded-full bg-background shadow-sm'
          aria-label={t('chat.scrollToBottom', 'Scroll to bottom')}
          onClick={() => scrollToBottom()}
        >
          <ArrowDown aria-hidden='true' />
        </Button>
      ) : null}
    </div>
  );
}

import { useTranslation } from '@nocobase/i18n/client';
import { cn } from 'cn';
import {
  useAIChatBase,
  type AIToolCallDecision,
} from '../../providers/index.js';
import { useRef, useState, type DragEvent, type ReactNode } from 'react';
import { ChatComposer, type AIChatComposerAction } from './chat-composer.js';
import { ChatHeader } from './chat-header.js';
import { ChatMessages } from './chat-messages.js';
import { ConversationList } from './conversation-list.js';

export function AIChatWindow({
  className,
  headerActions,
  composerActions,
  showConversationToggle = true,
  showNewConversation = true,
  showEmployeeSelector = true,
  showModelSelector = true,
  showUserPrompt = true,
  enableAttachments = false,
  enableWebSearch = false,
  attachmentActionIndex = 0,
  placeholder,
  disclaimer,
  onToolCallDecision,
}: AIChatWindowProps) {
  const { t } = useTranslation('@nocobase/app-plugin-ai-employee');
  const { conversationListOpen, setConversationListOpen, uploadFiles } =
    useAIChatBase();
  const [draggingFiles, setDraggingFiles] = useState(false);
  const dragDepthRef = useRef(0);

  const hasFiles = (event: DragEvent) =>
    Array.from(event.dataTransfer.types).includes('Files');

  return (
    <section
      className={cn(
        'ai-chat-window relative flex h-full min-h-0 w-full overflow-hidden bg-background text-foreground',
        className,
      )}
      onDragEnter={(event) => {
        if (!enableAttachments || !hasFiles(event)) return;
        event.preventDefault();
        dragDepthRef.current += 1;
        setDraggingFiles(true);
      }}
      onDragOver={(event) => {
        if (!enableAttachments || !hasFiles(event)) return;
        event.preventDefault();
        event.dataTransfer.dropEffect = 'copy';
      }}
      onDragLeave={(event) => {
        if (!enableAttachments || !hasFiles(event)) return;
        event.preventDefault();
        dragDepthRef.current = Math.max(0, dragDepthRef.current - 1);
        if (dragDepthRef.current === 0) setDraggingFiles(false);
      }}
      onDrop={(event) => {
        if (!enableAttachments || !hasFiles(event)) return;
        event.preventDefault();
        dragDepthRef.current = 0;
        setDraggingFiles(false);
        const files = Array.from(event.dataTransfer.files);
        if (files.length) void uploadFiles(files);
      }}
    >
      {draggingFiles ? (
        <div className='pointer-events-none absolute inset-2 z-50 flex items-center justify-center rounded-xl border-2 border-dashed border-foreground/25 bg-background/90 text-sm font-medium shadow-sm backdrop-blur-sm'>
          {t('chat.dropFiles', 'Drop files to upload')}
        </div>
      ) : null}
      {conversationListOpen && showConversationToggle ? (
        <button
          type='button'
          className='ai-chat-conversation-backdrop absolute inset-0 z-20 bg-black/25 backdrop-blur-[1px]'
          aria-label={t(
            'chat.closeConversationList',
            'Close conversation list',
          )}
          onClick={() => setConversationListOpen(false)}
        />
      ) : null}
      {conversationListOpen && showConversationToggle ? (
        <aside className='ai-chat-conversation-panel z-30 flex h-full w-[300px] shrink-0 border-r bg-card'>
          <ConversationList />
        </aside>
      ) : null}
      <div className='flex min-w-0 flex-1 flex-col'>
        <ChatHeader
          actions={headerActions}
          showConversationToggle={showConversationToggle}
          showNewConversation={showNewConversation}
          showUserPrompt={showUserPrompt}
        />
        <ChatMessages onToolCallDecision={onToolCallDecision} />
        <ChatComposer
          actions={composerActions}
          showEmployeeSelector={showEmployeeSelector}
          showModelSelector={showModelSelector}
          enableAttachments={enableAttachments}
          enableWebSearch={enableWebSearch}
          attachmentActionIndex={attachmentActionIndex}
          placeholder={placeholder}
          disclaimer={disclaimer}
        />
      </div>
    </section>
  );
}

