const getPartKey = (
  part: AISubAgentConversationType['messages'][number]['parts'][number],
) => {
  if (part.type === 'data-subAgent') return part.id ?? part.data.sessionId;
  if (isToolCallPart(part)) return part.toolCallId;
  return part.type;
};

type SubAgentConversationProps = {
  conversation: AISubAgentConversationType;
  onToolCallDecision?: (decision: AIToolCallDecision) => void | Promise<void>;
  status?: 'submitted' | 'streaming' | 'ready' | 'error';
  decideToolCall?: (decision: AIToolCallDecision) => Promise<void>;
  focusComposer?: () => void;
  readOnly?: boolean;
};

export function SubAgentConversation(props: SubAgentConversationProps) {
  return props.readOnly ? (
    <SubAgentConversationView {...props} />
  ) : (
    <ConnectedSubAgentConversation {...props} />
  );
}

function ConnectedSubAgentConversation(props: SubAgentConversationProps) {
  const ai = useAI();
  return (
    <SubAgentConversationView
      {...props}
      employee={ai.employees.find(
        (item) => item.username === props.conversation.username,
      )}
    />
  );
}

function SubAgentConversationView({
  conversation,
  onToolCallDecision,
  status = 'ready',
  decideToolCall,
  focusComposer,
  readOnly = false,
  employee = {
    username: conversation.username,
    nickname: conversation.username,
  },
}: SubAgentConversationProps & { employee?: AIEmployee }) {
  const { t } = useTranslation('@nocobase/app-plugin-ai-employee');
  const completed = conversation.status === 'completed';
  const [expanded, setExpanded] = useState(true);
  const messages =
    conversation.messages[0]?.role === 'user'
      ? conversation.messages.slice(1)
      : conversation.messages;
  const interactionPending = status === 'streaming' || status === 'submitted';

  return (
    <section className='min-w-0 max-w-full rounded-xl border border-dashed bg-muted/15'>
      <Button
        type='button'
        variant='ghost'
        className='h-auto w-full justify-start rounded-xl px-3 py-2 text-left'
        onClick={() => setExpanded((current) => !current)}
      >
        {expanded ? (
          <ChevronDown className='size-4 shrink-0' />
        ) : (
          <ChevronRight className='size-4 shrink-0' />
        )}
        <AIEmployeeAvatar employee={employee} className='size-6' />
        <span className='min-w-0 flex-1 truncate text-sm font-medium'>
          {employee.nickname}
        </span>
        <span className='flex shrink-0 items-center gap-1.5 text-xs font-normal text-muted-foreground'>
          {!completed ? <LoaderCircle className='size-3 animate-spin' /> : null}
          {completed
            ? t('tool.status.completed', 'Completed')
            : t('tool.subAgent.statusWorking', 'Working')}
        </span>
      </Button>
      {expanded ? (
        <div className='min-w-0 space-y-3 border-t border-dashed px-3 py-3'>
          {messages.flatMap((message) =>
            withStableKeys(message.parts, getPartKey).map(
              ({ key, item: part }) => {
                if (part.type === 'reasoning') {
                  return (
                    <ReasoningPanel
                      key={`${message.id}-${key}`}
                      streaming={part.state === 'streaming'}
                    >
                      {part.text}
                    </ReasoningPanel>
                  );
                }
                if (part.type === 'text') {
                  return (
                    <div
                      key={`${message.id}-${key}`}
                      className='ai-markdown min-w-0 max-w-full [overflow-wrap:anywhere] text-sm leading-6 text-foreground'
                    >
                      <MarkdownMessage>{part.text}</MarkdownMessage>
                    </div>
                  );
                }
                if (part.type === 'data-subAgent') {
                  return (
                    <SubAgentConversation
                      key={`${message.id}-${key}`}
                      conversation={part.data}
                      readOnly={readOnly}
                      onToolCallDecision={onToolCallDecision}
                      status={status}
                      decideToolCall={decideToolCall}
                      focusComposer={focusComposer}
                    />
                  );
                }
                if (!isToolCallPart(part)) return [];
                return (
                  <ToolCallCard
                    key={`${message.id}-${key}`}
                    part={part}
                    approval={
                      message.metadata?.toolApprovals?.[part.toolCallId]
                    }
                    disabled={interactionPending}
                    readOnly={readOnly}
                    onRevise={focusComposer}
                    onDecision={async (decision, input) => {
                      if (readOnly) return;
                      const toolDecision = {
                        messageId: message.id,
                        toolCallId: part.toolCallId,
                        toolName: getToolCallName(part),
                        decision,
                        input,
                      } satisfies AIToolCallDecision;
                      await decideToolCall?.(toolDecision);
                      await onToolCallDecision?.(toolDecision);
                    }}
                  />
                );
              },
            ),
          )}
          {!messages.length ? (
            <div
              className={cn(
                'text-xs text-muted-foreground',
                !completed && 'animate-pulse',
              )}
            >
              {completed
                ? t('tool.subAgent.noOutput', 'No visible output.')
                : t('tool.subAgent.starting', 'Starting delegated work…')}
            </div>
          ) : null}
        </div>
      ) : null}
    </section>
  );
}

import { useTranslation } from '@nocobase/i18n/client';
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from '../../shared/ui/collapsible.js';
import { Button } from '../../shared/ui/button.js';
import { cn } from 'cn';
import type { AIToolCallApproval } from '../../providers/index.js';
import {
  Check,
  ChevronDown,
  CircleAlert,
  LoaderCircle,
  Wrench,
} from 'lucide-react';
import { useState, type ReactNode } from 'react';
import { useAIToolRenderer } from '../tools/tool-renderer-context.js';
import { getToolCallName, type ToolCallPart } from './tool-call-utils.js';

const toolLabel = (part: ToolCallPart) =>
  getToolCallName(part)
    .replace(/([a-z0-9])([A-Z])/g, '$1 $2')
    .replace(/[-_]+/g, ' ')
    .replace(/^./, (character) => character.toUpperCase());

const formatValue = (value: unknown) => {
  if (typeof value === 'string') return value;
  try {
    return JSON.stringify(value, null, 2) ?? String(value);
  } catch {
    return String(value);
  }
};

const getStatus = (
  part: ToolCallPart,
  t: (key: string, defaultValue: string) => string,
) => {
  switch (part.state) {
    case 'input-streaming':
      return {
        label: t('tool.status.preparing', 'Preparing'),
        icon: LoaderCircle,
        tone: 'text-muted-foreground',
      };
    case 'input-available':
      return {
        label: t('tool.status.running', 'Running'),
        icon: LoaderCircle,
        tone: 'text-muted-foreground',
      };
    case 'output-error':
      return {
        label: t('tool.status.failed', 'Failed'),
        icon: CircleAlert,
        tone: 'text-destructive',
      };
    case 'output-available':
      return {
        label: t('tool.status.completed', 'Completed'),
        icon: Check,
        tone: 'text-foreground',
      };
  }
};

const approvalFromPart = (
  part: ToolCallPart,
): AIToolCallApproval | undefined => {
  if (!('callProviderMetadata' in part)) return undefined;
  const metadata = part.callProviderMetadata?.nocobase;
  if (!metadata || typeof metadata !== 'object') return undefined;
  const requiresApproval = (metadata as { requiresApproval?: unknown })
    .requiresApproval;
  return requiresApproval === true
    ? { required: true, status: 'pending' }
    : undefined;
};

type ToolCallCardProps = {
  part: ToolCallPart;
  approval?: AIToolCallApproval;
  onDecision?: (
    decision: 'approve' | 'reject' | 'edit',
    input?: unknown,
  ) => void | Promise<void>;
  onRevise?: () => void;
  inlineActions?: ReactNode;
  disabled?: boolean;
  readOnly?: boolean;
};

export function ToolCallCard({
  part,
  approval,
  onDecision,
  onRevise,
  inlineActions,
  disabled = false,
  readOnly = false,
}: ToolCallCardProps) {
  const { t } = useTranslation('@nocobase/app-plugin-ai-employee');
  const resolvedApproval = approval ?? approvalFromPart(part);
  const [approvalStatus, setApprovalStatus] = useState(
    resolvedApproval?.status ?? 'pending',
  );
  const [deciding, setDeciding] = useState(false);
  const renderer = useAIToolRenderer(getToolCallName(part));
  // Custom renderers can invoke tools on mount; disabled controls alone are not a read-only boundary.
  const Renderer = readOnly ? undefined : renderer?.component;
  const [open, setOpen] = useState(false);
  const toolStatus = getStatus(part, t);
  const approvalRequired =
    resolvedApproval?.required === true && approvalStatus === 'pending';
  const status = approvalRequired
    ? {
        label: t('tool.status.approvalRequired', 'Approval required'),
        icon: CircleAlert,
        tone: 'text-foreground',
      }
    : approvalStatus === 'rejected'
      ? {
          label: t('tool.status.denied', 'Denied'),
          icon: CircleAlert,
          tone: 'text-muted-foreground',
        }
      : approvalStatus === 'approved' && part.state === 'input-available'
        ? {
            label: t('tool.status.allowed', 'Allowed'),
            icon: Check,
            tone: 'text-foreground',
          }
        : toolStatus;
  const StatusIcon = status.icon;
  const hasInput = part.input !== undefined;
  const hasError = part.state === 'output-error';

  const [syncedApprovalStatus, setSyncedApprovalStatus] = useState(
    resolvedApproval?.status,
  );
  if (syncedApprovalStatus !== resolvedApproval?.status) {
    setSyncedApprovalStatus(resolvedApproval?.status);
    setApprovalStatus(resolvedApproval?.status ?? 'pending');
  }

  const decide = async (
    decision: 'approve' | 'reject' | 'edit',
    input?: unknown,
  ) => {
    if (disabled || readOnly) return;
    setDeciding(true);
    try {
      await onDecision?.(decision, input);
      setApprovalStatus(decision === 'reject' ? 'rejected' : 'approved');
    } finally {
      setDeciding(false);
    }
  };

  if (Renderer && renderer?.standalone) {
    const specializedDisabled =
      disabled ||
      approvalStatus === 'rejected' ||
      (resolvedApproval?.required === true && approvalStatus !== 'pending');
    return (
      <div>
        <Renderer
          part={part}
          disabled={specializedDisabled}
          onEdit={(input) => onDecision?.('edit', input)}
          onApprove={() => onDecision?.('approve')}
          onReject={(message) => onDecision?.('reject', message)}
          onRevise={() => onRevise?.()}
        />
        {part.state === 'output-error' ? (
          <div className='mt-2 rounded-lg border border-destructive/30 bg-destructive/5 px-3 py-2 text-xs text-destructive'>
            {part.errorText}
          </div>
        ) : null}
      </div>
    );
  }

  return (
    <Collapsible
      open={open}
      onOpenChange={setOpen}
      className='overflow-hidden rounded-lg border border-border/70 bg-muted/30'
    >
      <div className='flex items-center'>
        <CollapsibleTrigger className='group/tool-call flex min-w-0 flex-1 items-center gap-2 px-3 py-2 text-left text-xs font-medium text-muted-foreground outline-none hover:bg-muted/40 hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-inset'>
          <Wrench className='size-3.5 shrink-0' />
          <span className='min-w-0 flex-1 truncate'>{toolLabel(part)}</span>
          <span
            className={cn(
              'flex shrink-0 items-center gap-1.5 font-normal',
              status.tone,
            )}
          >
            <StatusIcon
              className={cn(
                'size-3.5',
                (deciding ||
                  (!approvalRequired &&
                    approvalStatus === 'pending' &&
                    (part.state === 'input-streaming' ||
                      part.state === 'input-available'))) &&
                  'animate-spin',
              )}
            />
            {deciding ? t('tool.status.applying', 'Applying…') : status.label}
          </span>
          <ChevronDown className='size-3.5 shrink-0 transition-transform group-data-panel-open/tool-call:rotate-180' />
        </CollapsibleTrigger>
        {inlineActions && !readOnly ? (
          <div className='flex shrink-0 items-center pr-2'>{inlineActions}</div>
        ) : null}
      </div>
      {approvalRequired && !readOnly && !renderer?.handlesApproval ? (
        <div className='flex items-center justify-between gap-3 border-t px-3 py-2.5'>
          <p className='text-xs text-muted-foreground'>
            {t(
              'tool.permission.description',
              'This tool needs permission before it can run.',
            )}
          </p>
          <div className='flex shrink-0 items-center gap-2'>
            <Button
              variant='ghost'
              size='sm'
              disabled={disabled || deciding}
              onClick={() => void decide('reject')}
            >
              {t('actions.deny', 'Deny')}
            </Button>
            <Button
              size='sm'
              disabled={disabled || deciding}
              onClick={() => void decide('approve')}
            >
              {t('actions.allow', 'Allow')}
            </Button>
          </div>
        </div>
      ) : null}
      <CollapsibleContent className='border-t'>
        {Renderer ? (
          <div className='p-3'>
            <Renderer
              part={part}
              disabled={
                disabled ||
                deciding ||
                approvalStatus === 'rejected' ||
                (resolvedApproval?.required === true &&
                  approvalStatus !== 'pending')
              }
              onEdit={(input) => decide('edit', input)}
              onApprove={() => decide('approve')}
              onReject={() => decide('reject')}
              onRevise={() => onRevise?.()}
            />
          </div>
        ) : hasInput ? (
          <ToolCallValue label={t('tool.input', 'Input')} value={part.input} />
        ) : null}
        {readOnly && part.state === 'output-available' ? (
          <ToolCallValue
            label={t('tool.output', 'Output')}
            value={part.output}
          />
        ) : null}
        {part.state === 'output-error' ? (
          <ToolCallValue
            label={t('tool.error', 'Error')}
            value={part.errorText}
            error
          />
        ) : null}
        {!Renderer &&
        !hasInput &&
        !hasError &&
        !(readOnly && part.state === 'output-available') ? (
          <p className='px-3 py-3 text-xs text-muted-foreground'>
            {t('tool.waitingInput', 'Waiting for tool input…')}
          </p>
        ) : null}
      </CollapsibleContent>
    </Collapsible>
  );
}

function ToolCallValue({
  label,
  value,
  error = false,
}: {
  label: string;
  value: unknown;
  error?: boolean;
}) {
  return (
    <div className='border-b px-3 py-3 last:border-b-0'>
      <div className='mb-1.5 text-[11px] font-medium uppercase tracking-wide text-muted-foreground'>
        {label}
      </div>
      <pre
        className={cn(
          'max-h-48 overflow-auto whitespace-pre-wrap break-words rounded-lg bg-background p-2.5 font-mono text-xs leading-5',
          error && 'text-destructive',
        )}
      >
        {formatValue(value)}
      </pre>
    </div>
  );
}

import type { AIChatMessage } from '../../providers/index.js';

export type ToolCallPart = Extract<
  AIChatMessage['parts'][number],
  { type: `tool-${string}` | 'dynamic-tool' }
>;

export function isToolCallPart(
  part: AIChatMessage['parts'][number],
): part is ToolCallPart {
  return part.type === 'dynamic-tool' || part.type.startsWith('tool-');
}

export const getToolCallName = (part: ToolCallPart) =>
  part.type === 'dynamic-tool' ? part.toolName : part.type.slice(5);

export type NocoBaseToolCallMetadata = {
  autoApprove?: boolean;
  invokeStatus?: string;
  messageId?: string;
  requiresApproval?: boolean;
  selectedSuggestion?: string;
  status?: string;
};

export const getNocoBaseToolCallMetadata = (part: ToolCallPart) => {
  if (!('callProviderMetadata' in part)) return undefined;
  const metadata = part.callProviderMetadata?.nocobase;
  return metadata && typeof metadata === 'object'
    ? (metadata as NocoBaseToolCallMetadata)
    : undefined;
};

import { useTranslation } from '@nocobase/i18n/client';
import { Button } from '../../shared/ui/button.js';
import {
  Popover,
  PopoverContent,
  PopoverDescription,
  PopoverHeader,
  PopoverTitle,
  PopoverTrigger,
} from '../../shared/ui/popover.js';
import { Textarea } from '../../shared/ui/textarea.js';
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from '../../shared/ui/tooltip.js';
import { MessageSquareText } from 'lucide-react';
import { useState } from 'react';
import { useAIChatBase } from '../../providers/index.js';

export function UserPromptEditor() {
  const { t } = useTranslation('@nocobase/app-plugin-ai-employee');
  const { currentEmployee, saveUserPrompt } = useAIChatBase();
  const [open, setOpen] = useState(false);
  const [prompt, setPrompt] = useState('');
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string>();

  // Seed the draft while rendering rather than in an effect: the popover would
  // otherwise render once with the previous employee's prompt.
  const savedPrompt = currentEmployee.userConfig?.prompt ?? '';
  const promptSource = open
    ? `${currentEmployee.username}:${savedPrompt}`
    : undefined;
  const [syncedPromptSource, setSyncedPromptSource] = useState(promptSource);
  if (syncedPromptSource !== promptSource) {
    setSyncedPromptSource(promptSource);
    if (open) {
      setPrompt(savedPrompt);
      setError(undefined);
    }
  }

  const save = async () => {
    setSaving(true);
    setError(undefined);
    try {
      await saveUserPrompt(prompt);
      setOpen(false);
    } catch (saveError) {
      setError(
        saveError instanceof Error
          ? saveError.message
          : t('chat.prompt.saveError', 'Unable to save prompt'),
      );
    } finally {
      setSaving(false);
    }
  };

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <Tooltip>
        <TooltipTrigger
          render={
            <PopoverTrigger
              render={
                <Button
                  variant='ghost'
                  size='icon-sm'
                  aria-label={t('chat.prompt.title', 'Personalized prompt')}
                />
              }
            />
          }
        >
          <MessageSquareText />
        </TooltipTrigger>
        <TooltipContent>
          {t('chat.prompt.title', 'Personalized prompt')}
        </TooltipContent>
      </Tooltip>
      <PopoverContent
        align='end'
        sideOffset={8}
        className='w-[380px] gap-3 p-4'
      >
        <PopoverHeader>
