        <div className='flex justify-end gap-2'>
          <Button variant='outline' size='sm' onClick={() => setOpen(false)}>
            {t('actions.cancel', 'Cancel')}
          </Button>
          <Button size='sm' disabled={saving} onClick={() => void save()}>
