  useContext(AIPageContextScopeContext);

import type { AIEmployeeTask, AIWorkContextItem } from './types.js';

export function createAIPageContextReference({
  id,
  title,
  kind,
}: {
  id: string;
  title: string;
  kind?: string;
}): AIWorkContextItem {
  return {
    type: 'page-element',
    id,
    title,
    ...(kind ? { kind } : {}),
  };
}

const isFormContext = (item: AIWorkContextItem) => {
  if (item.kind === 'form') return true;
  if (!item.content || typeof item.content !== 'object') return false;
  const content = item.content as Record<string, unknown>;
  return typeof content.form === 'string' && Array.isArray(content.fields);
};

export function getAIWorkContextRequiredTools(
  items: AIWorkContextItem[],
): string[] {
  return items.some(isFormContext) ? ['formFiller'] : [];
}

export function getAIWorkContextToolScope(items: AIWorkContextItem[]): {
  allowedFrontendToolIds: string[];
  allowedFormIds: string[];
} {
  const frontendToolIds = new Set<string>();
  const formIds = new Set<string>();
  for (const item of items) {
    if (Array.isArray(item.frontendTools)) {
      for (const tool of item.frontendTools) {
        if (
          tool &&
          typeof tool === 'object' &&
          typeof (tool as { id?: unknown }).id === 'string'
        ) {
          frontendToolIds.add((tool as { id: string }).id);
        }
      }
    }
    if (isFormContext(item)) {
      const form = (item.content as { form?: unknown } | undefined)?.form;
      if (typeof form === 'string' && form) formIds.add(form);
    }
  }
  return {
    allowedFrontendToolIds: [...frontendToolIds],
    allowedFormIds: [...formIds],
  };
}

/**
 * Adds the tools a work context needs to a task's tool allowlist. The server
 * reads a non-empty `tools` list as the only tools the session may use, so
 * without an allowlist there is nothing to add to: the employee's tools are
 * all available already, and creating a list here would hide every other one.
 */
export function mergeAIRequiredTools(
  skillSettings: AIEmployeeTask['skillSettings'],
  requiredTools: string[],
): AIEmployeeTask['skillSettings'] {
  const tools = skillSettings?.tools;
  if (!requiredTools.length || !tools?.length) return skillSettings;
  return {
    ...skillSettings,
    tools: [...new Set([...tools, ...requiredTools])],
  };
}

import { useContext, useMemo, type PropsWithChildren } from 'react';
import type { AIWorkContextItem } from './types.js';
import {
  AIPageContextResolverContext,
  AIPageContextScopeContext,
  type AIPageContextResolver,
} from './page-context-store.js';

export function AIPageContextResolverProvider({
  resolve,
  children,
}: PropsWithChildren<{ resolve: AIPageContextResolver }>) {
  return (
    <AIPageContextResolverContext.Provider value={resolve}>
      {children}
    </AIPageContextResolverContext.Provider>
  );
}

export function AIPageContextScope({
  context,
  mode = 'replace',
  children,
}: PropsWithChildren<{
  context: AIWorkContextItem | AIWorkContextItem[];
  mode?: 'replace' | 'append';
}>) {
  const inheritedContext = useContext(AIPageContextScopeContext);
  const value = useMemo(() => {
    const ownContext = Array.isArray(context) ? context : [context];
    if (mode !== 'append') return ownContext;
    const combined = [...inheritedContext, ...ownContext];
    return combined.filter((item, index) => {
      if (!item.id) return true;
      return (
        combined.findLastIndex(
          (candidate) =>
            candidate.type === item.type && candidate.id === item.id,
        ) === index
      );
    });
  }, [context, inheritedContext, mode]);
  return (
    <AIPageContextScopeContext.Provider value={value}>
      {children}
    </AIPageContextScopeContext.Provider>
  );
}

export type StreamCoalescerOptions<Key, Value> = {
  interval: number;
  maxSize: number;
  getSize: (value: Value) => number;
  merge: (current: Value, incoming: Value) => Value;
  onFlush: (key: Key, value: Value) => void;
};

type PendingValue<Value> = {
  value: Value;
  timer: ReturnType<typeof setTimeout>;
};

export class StreamCoalescer<Key, Value> {
  private readonly pending = new Map<Key, PendingValue<Value>>();

  constructor(private readonly options: StreamCoalescerOptions<Key, Value>) {}

  push(key: Key, value: Value) {
    const existing = this.pending.get(key);
    if (existing) {
      existing.value = this.options.merge(existing.value, value);
      if (this.options.getSize(existing.value) >= this.options.maxSize) {
        this.flush(key);
      }
      return;
    }

    const timer = setTimeout(() => this.flush(key), this.options.interval);
    this.pending.set(key, { value, timer });
    if (this.options.getSize(value) >= this.options.maxSize) {
      this.flush(key);
    }
  }

  has(key: Key) {
    return this.pending.has(key);
  }

  flush(key: Key) {
    const pending = this.pending.get(key);
    if (!pending) return;
    clearTimeout(pending.timer);
    this.pending.delete(key);
    this.options.onFlush(key, pending.value);
  }

  flushAll() {
    for (const key of [...this.pending.keys()]) {
      this.flush(key);
    }
  }

  clear() {
    for (const pending of this.pending.values()) {
      clearTimeout(pending.timer);
    }
    this.pending.clear();
  }
}

import type { NocoBaseStreamEvent } from './stream-parser.js';

export type NocoBaseToolCall = {
  id?: string;
  index?: number;
  name?: string;
  args?: unknown;
  input?: unknown;
  output?: unknown;
  content?: unknown;
  status?: string;
  invokeStatus?: string;
  invokeStartTime?: unknown;
  invokeEndTime?: unknown;
  messageId?: string;
  willInterrupt?: boolean;
  auto?: boolean;
  selectedSuggestion?: string;
};

export const isRecord = (value: unknown): value is Record<string, unknown> =>
  !!value && typeof value === 'object' && !Array.isArray(value);

export const toolCallsFromEvent = (event: NocoBaseStreamEvent) => {
  if (Array.isArray(event.body)) return event.body as NocoBaseToolCall[];
  if (!isRecord(event.body) || !Array.isArray(event.body.toolCalls)) return [];
  return event.body.toolCalls as NocoBaseToolCall[];
};

export const parseToolInput = (input: unknown) => {
  if (typeof input !== 'string') return input;
  try {
    return JSON.parse(input) as unknown;
  } catch {
    return input;
  }
};

const completedToolStatus = new Set(['success', 'done', 'confirmed']);
const failedToolStatus = new Set(['error', 'failed', 'rejected']);
const pendingInvokeStatus = new Set([
  'interrupted',
  'waiting',
  'pending',
  'running',
]);

export const getToolCallState = (toolCall: NocoBaseToolCall) => {
  const invokeStatus = String(toolCall.invokeStatus ?? '').toLowerCase();
  const resultStatus = String(toolCall.status ?? '').toLowerCase();
  const failed =
    failedToolStatus.has(invokeStatus) || failedToolStatus.has(resultStatus);
  const completed =
    !failed &&
    (completedToolStatus.has(invokeStatus) ||
      (!invokeStatus && completedToolStatus.has(resultStatus)));
  return {
    invokeStatus,
    resultStatus,
    failed,
    completed,
    pending: !failed && !completed && pendingInvokeStatus.has(invokeStatus),
  };
};

export const getToolProviderMetadata = (toolCall: NocoBaseToolCall) => {
  const { invokeStatus, resultStatus } = getToolCallState(toolCall);
  return {
    nocobase: {
      requiresApproval:
        (invokeStatus === 'interrupted' ||
          (!invokeStatus && toolCall.willInterrupt === true)) &&
        toolCall.auto !== true,
      autoApprove: invokeStatus === 'interrupted' && toolCall.auto === true,
      invokeStatus,
      ...(typeof toolCall.selectedSuggestion === 'string'
        ? { selectedSuggestion: toolCall.selectedSuggestion }
        : {}),
      status: resultStatus,
    },
  };
};

import {
  createParser,
  type EventSourceMessage,
  type ParseError,
} from 'eventsource-parser';

export type NocoBaseStreamEvent = {
  type: string;
  body?: unknown;
  sessionId?: string;
  from?: string;
  username?: string;
  errorName?: string;
  /** On an `error` event from a failed agent run, its `AgentServiceError` code. */
  code?: string;
};

const MAX_SSE_BUFFER_SIZE = 16 * 1024 * 1024;

export async function* parseNocoBaseSSE(
  stream: ReadableStream<Uint8Array>,
): AsyncGenerator<NocoBaseStreamEvent> {
  const reader = stream.getReader();
  const decoder = new TextDecoder();
  const events: EventSourceMessage[] = [];
  let parseError: ParseError | undefined;
  const parser = createParser({
    maxBufferSize: MAX_SSE_BUFFER_SIZE,
    onEvent: (event) => events.push(event),
    onError: (error) => {
      parseError = error;
    },
  });

  const drainEvents = function* () {
    while (events.length) {
      const event = events.shift();
      if (!event) continue;
      const payload = event.data.trim();
      if (!payload || payload === '[DONE]') continue;
      yield JSON.parse(payload) as NocoBaseStreamEvent;
    }
  };

  try {
    while (true) {
      const { done, value } = await reader.read();
      if (value) parser.feed(decoder.decode(value, { stream: true }));
      if (parseError) {
        throw new Error('Unable to parse the NocoBase event stream', {
          cause: parseError,
        });
      }
      yield* drainEvents();
      if (!done) continue;

      const remainder = decoder.decode();
      if (remainder) parser.feed(remainder);
      parser.reset({ consume: true });
      if (parseError) {
        throw new Error('Unable to parse the NocoBase event stream', {
          cause: parseError,
        });
      }
      yield* drainEvents();
      return;
    }
  } finally {
    reader.releaseLock();
  }
}

import type { InferUIMessageChunk } from 'ai';
import type { AIChatMessage, AISubAgentConversation } from './types.js';
import type { NocoBaseStreamEvent } from './stream-parser.js';
import { toText } from '../shared/text.js';
import {
  getToolCallState,
  getToolProviderMetadata,
  isRecord,
  parseToolInput,
  toolCallsFromEvent,
  type NocoBaseToolCall,
} from './stream-event-utils.js';

type AIChatChunk = InferUIMessageChunk<AIChatMessage>;

const createMessage = (username: string): AIChatMessage => ({
  id: `sub-agent-${crypto.randomUUID()}`,
  role: 'assistant',
  metadata: {
    createdAt: new Date().toISOString(),
    employeeUsername: username,
  },
  parts: [],
});

const updateLastMessage = (
  conversation: AISubAgentConversation,
  updater: (message: AIChatMessage) => AIChatMessage,
) => {
  const messages = conversation.messages.length
    ? [...conversation.messages]
    : [createMessage(conversation.username)];
  messages[messages.length - 1] = updater(messages[messages.length - 1]);
  return { ...conversation, messages };
};

const appendNarrative = (
  message: AIChatMessage,
  type: 'text' | 'reasoning',
  delta: string,
): AIChatMessage => {
  const parts = [...message.parts];
  const last = parts.at(-1);
  if (last?.type === type) {
    parts[parts.length - 1] = {
      ...last,
      text: `${last.text}${delta}`,
      state: 'streaming',
    };
  } else {
    parts.push({ type, text: delta, state: 'streaming' });
  }
  return { ...message, parts };
};

const toToolPart = (
  toolCall: NocoBaseToolCall,
): AIChatMessage['parts'][number] => {
  const toolCallId = toolCall.id ?? `tool-${crypto.randomUUID()}`;
  const toolName = toolCall.name ?? 'tool';
  const input = parseToolInput(toolCall.args ?? toolCall.input ?? {});
  const state = getToolCallState(toolCall);
  const callProviderMetadata = getToolProviderMetadata(toolCall);
  if (state.failed) {
    return {
      type: 'dynamic-tool',
      toolCallId,
      toolName,
      state: 'output-error',
      input,
      errorText: toText(
        toolCall.content ?? toolCall.output,
        'Tool call failed',
      ),
      callProviderMetadata,
    };
  }
  if (state.completed) {
    return {
      type: 'dynamic-tool',
      toolCallId,
      toolName,
      state: 'output-available',
      input,
      output: toolCall.output ?? toolCall.content ?? { status: 'completed' },
      callProviderMetadata,
    };
  }
  return {
    type: 'dynamic-tool',
    toolCallId,
    toolName,
    state: 'input-available',
    input,
    callProviderMetadata,
  };
};

const updateToolCalls = (
  message: AIChatMessage,
  toolCalls: NocoBaseToolCall[],
) => {
  const parts = [...message.parts];
  for (const toolCall of toolCalls) {
    const nextPart = toToolPart(toolCall);
    if (nextPart.type !== 'dynamic-tool') continue;
    const index = parts.findIndex(
      (part) =>
        part.type === 'dynamic-tool' && part.toolCallId === nextPart.toolCallId,
    );
    if (index >= 0) parts[index] = nextPart;
    else parts.push(nextPart);
  }
  return { ...message, parts };
};

const finishMessages = (messages: AIChatMessage[]) =>
  messages.map((message) => ({
    ...message,
    parts: message.parts.map((part) =>
      part.type === 'text' || part.type === 'reasoning'
        ? { ...part, state: 'done' as const }
        : part,
    ),
  }));

export class SubAgentStreamAccumulator {
  private readonly conversations = new Map<string, AISubAgentConversation>();
  private readonly toolStreams = new Map<
    string,
    {
      currentId?: string;
      idsByIndex: Map<number, string>;
      names: Map<string, string>;
      inputs: Map<string, unknown>;
    }
  >();

  constructor(seedMessage?: AIChatMessage) {
    if (!seedMessage) return;
    const seed = (messages: AIChatMessage[]) => {
      for (const message of messages) {
        for (const part of message.parts) {
          if (part.type !== 'data-subAgent') continue;
          this.conversations.set(
            part.data.sessionId,
            structuredClone(part.data),
          );
          seed(part.data.messages);
        }
      }
    };
    seed([seedMessage]);
  }

  private getToolStream(sessionId: string) {
    const existing = this.toolStreams.get(sessionId);
    if (existing) return existing;
    const created = {
      currentId: undefined,
      idsByIndex: new Map<number, string>(),
      names: new Map<string, string>(),
      inputs: new Map<string, unknown>(),
    };
    this.toolStreams.set(sessionId, created);
    return created;
  }

  private normalizeToolChunk(
    sessionId: string,
    chunk: NocoBaseToolCall,
  ): NocoBaseToolCall | undefined {
    const stream = this.getToolStream(sessionId);
    const indexedId =
      typeof chunk.index === 'number'
        ? stream.idsByIndex.get(chunk.index)
        : undefined;
    const toolCallId = chunk.id ?? indexedId ?? stream.currentId;
    if (!toolCallId) return undefined;

    stream.currentId = toolCallId;
    if (typeof chunk.index === 'number') {
      stream.idsByIndex.set(chunk.index, toolCallId);
    }
    if (chunk.name) stream.names.set(toolCallId, chunk.name);

    if (typeof chunk.args === 'string') {
      const previous = stream.inputs.get(toolCallId);
      stream.inputs.set(
        toolCallId,
        `${typeof previous === 'string' ? previous : ''}${chunk.args}`,
      );
    } else if (chunk.args !== undefined) {
      stream.inputs.set(toolCallId, chunk.args);
    } else if (chunk.input !== undefined) {
      stream.inputs.set(toolCallId, chunk.input);
    }

    return {
      ...chunk,
      id: toolCallId,
      name: chunk.name ?? stream.names.get(toolCallId) ?? 'tool',
      args: stream.inputs.get(toolCallId),
    };
  }

  private normalizeToolCall(
    sessionId: string,
    toolCall: NocoBaseToolCall,
  ): NocoBaseToolCall {
    const stream = this.getToolStream(sessionId);
    const toolCallId =
      toolCall.id ?? stream.currentId ?? `tool-${crypto.randomUUID()}`;
    stream.currentId = toolCallId;
    if (typeof toolCall.index === 'number') {
      stream.idsByIndex.set(toolCall.index, toolCallId);
    }
    const toolName = toolCall.name ?? stream.names.get(toolCallId) ?? 'tool';
    stream.names.set(toolCallId, toolName);
    const input = toolCall.args ?? toolCall.input;
    if (input !== undefined) stream.inputs.set(toolCallId, input);
    return {
      ...toolCall,
      id: toolCallId,
      name: toolName,
      args: input ?? stream.inputs.get(toolCallId),
    };
  }

  process(event: NocoBaseStreamEvent): AIChatChunk[] {
    if (event.from !== 'sub-agent' || !event.sessionId) return [];
    const username = event.username || 'sub-agent';
    let conversation = this.conversations.get(event.sessionId) ?? {
      sessionId: event.sessionId,
      username,
      status: 'pending' as const,
      messages: [],
    };

    if (event.type === 'new_message') {
      this.getToolStream(event.sessionId).currentId = undefined;
      conversation = {
        ...conversation,
        username,
        messages: [...conversation.messages, createMessage(username)],
      };
    } else if (event.type === 'content' && typeof event.body === 'string') {
      conversation = updateLastMessage(conversation, (message) =>
        appendNarrative(message, 'text', event.body as string),
      );
    } else if (event.type === 'reasoning' && isRecord(event.body)) {
      const content = event.body.content;
      if (typeof content === 'string' && content) {
        conversation = updateLastMessage(conversation, (message) =>
          appendNarrative(message, 'reasoning', content),
        );
      }
    } else if (event.type === 'tool_call_chunks') {
      const toolCalls = toolCallsFromEvent(event).flatMap((toolCall) => {
        const normalized = this.normalizeToolChunk(event.sessionId!, toolCall);
        return normalized ? [normalized] : [];
      });
      if (toolCalls.length) {
        conversation = updateLastMessage(conversation, (message) =>
          updateToolCalls(message, toolCalls),
        );
      }
    } else if (event.type === 'tool_calls') {
      const toolCalls = toolCallsFromEvent(event).map((toolCall) =>
        this.normalizeToolCall(event.sessionId!, toolCall),
      );
      if (toolCalls.length) {
        conversation = updateLastMessage(conversation, (message) =>
          updateToolCalls(message, toolCalls),
        );
      }
    } else if (event.type === 'tool_call_status' && isRecord(event.body)) {
      const rawToolCall = isRecord(event.body.toolCall)
        ? ({
            ...event.body.toolCall,
            invokeStatus:
              event.body.invokeStatus ?? event.body.toolCall.invokeStatus,
            status: event.body.status ?? event.body.toolCall.status,
            content: event.body.content ?? event.body.toolCall.content,
          } as NocoBaseToolCall)
        : undefined;
      const toolCall = rawToolCall
        ? this.normalizeToolCall(event.sessionId, rawToolCall)
        : undefined;
      if (toolCall) {
        conversation = updateLastMessage(conversation, (message) => {
          const updated = updateToolCalls(message, [toolCall]);
          return toolCall.messageId
            ? {
                ...updated,
                metadata: {
                  ...updated.metadata,
                  serverMessageId: String(toolCall.messageId),
                },
              }
            : updated;
        });
      }
    } else if (event.type === 'sub_agent_completed') {
      conversation = {
        ...conversation,
        status: 'completed',
        messages: finishMessages(conversation.messages),
      };
    }

    this.conversations.set(event.sessionId, conversation);
    return [
      {
        type: 'data-subAgent',
        id: event.sessionId,
        data: conversation,
      },
    ];
  }
}

