import type { InferUIMessageChunk } from 'ai';
import { parseNocoBaseSSE, type NocoBaseStreamEvent } from './stream-parser.js';
import { StreamCoalescer } from './stream-coalescer.js';
import {
  getToolCallState,
  getToolProviderMetadata,
  isRecord,
  parseToolInput,
  toolCallsFromEvent,
  type NocoBaseToolCall,
} from './stream-event-utils.js';
import { SubAgentStreamAccumulator } from './sub-agent-stream.js';
import type { AIChatMessage } from './types.js';
import { toText } from '../shared/text.js';

const VISUAL_DELTA_FLUSH_INTERVAL = 50;
const VISUAL_DELTA_FLUSH_SIZE = 768;
const TOOL_INPUT_FLUSH_INTERVAL = 50;
const TOOL_INPUT_FLUSH_SIZE = 2048;

type AIChatChunk = InferUIMessageChunk<AIChatMessage>;

type BufferedVisualDelta = {
  type: 'text-delta' | 'reasoning-delta';
  id: string;
  delta: string;
};

type BufferedSubAgentEvent = {
  event: NocoBaseStreamEvent;
  content: string;
};

type BufferedSubAgentToolEvent = {
  event: NocoBaseStreamEvent;
  chunks: NocoBaseToolCall[];
  size: number;
};

const reasoningContent = (event: NocoBaseStreamEvent) => {
  if (typeof event.body === 'object' && event.body) {
    const content = (event.body as { content?: unknown }).content;
    return typeof content === 'string' ? content : '';
  }
  return '';
};

const mergeToolCallChunks = (
  current: BufferedSubAgentToolEvent,
  incoming: BufferedSubAgentToolEvent,
) => {
  const chunks = current.chunks.map((chunk) => ({ ...chunk }));
  for (const chunk of incoming.chunks) {
    const last = chunks.at(-1);
    if (
      last &&
      !chunk.name &&
      (chunk.id === undefined || chunk.id === last.id) &&
      (chunk.index === undefined || chunk.index === last.index) &&
      typeof chunk.args === 'string'
    ) {
      last.args = `${typeof last.args === 'string' ? last.args : ''}${
        chunk.args
      }`;
    } else {
      chunks.push({ ...chunk });
    }
  }
  return {
    event: incoming.event,
    chunks,
    size: current.size + incoming.size,
  };
};

export function createNocoBaseUIMessageStream(
  stream: ReadableStream<Uint8Array>,
  messageId: string | null = `assistant-${crypto.randomUUID()}`,
  options: { waitForNewMessage?: boolean; seedMessage?: AIChatMessage } = {},
): ReadableStream<AIChatChunk> {
  return new ReadableStream<AIChatChunk>({
    async start(controller) {
      let textId = `text-${crypto.randomUUID()}`;
      let reasoningId = `reasoning-${crypto.randomUUID()}`;
      let textStarted = false;
      let reasoningStarted = false;
      let currentToolCallId: string | undefined;
      let responseStarted = options.waitForNewMessage !== true;
      const announcedToolCalls = new Set<string>();
      const toolCallNames = new Map<string, string>();
      const toolCallInputs = new Map<string, unknown>();
      const subAgents = new SubAgentStreamAccumulator(options.seedMessage);
      controller.enqueue(
        messageId === null ? { type: 'start' } : { type: 'start', messageId },
      );

      const visualDeltas = new StreamCoalescer<string, BufferedVisualDelta>({
        interval: VISUAL_DELTA_FLUSH_INTERVAL,
        maxSize: VISUAL_DELTA_FLUSH_SIZE,
        getSize: (value) => value.delta.length,
        merge: (current, incoming) => ({
          ...incoming,
          delta: `${current.delta}${incoming.delta}`,
        }),
        onFlush: (_, value) => controller.enqueue(value),
      });

      const toolInputDeltas = new StreamCoalescer<string, string>({
        interval: TOOL_INPUT_FLUSH_INTERVAL,
        maxSize: TOOL_INPUT_FLUSH_SIZE,
        getSize: (value) => value.length,
        merge: (current, incoming) => `${current}${incoming}`,
        onFlush: (toolCallId, inputTextDelta) => {
          controller.enqueue({
            type: 'tool-input-delta',
            toolCallId,
            inputTextDelta,
          });
        },
      });

      const subAgentToolEvents = new StreamCoalescer<
        string,
        BufferedSubAgentToolEvent
      >({
        interval: TOOL_INPUT_FLUSH_INTERVAL,
        maxSize: TOOL_INPUT_FLUSH_SIZE,
        getSize: (value) => value.size,
        merge: mergeToolCallChunks,
        onFlush: (_, value) => {
          for (const chunk of subAgents.process({
            ...value.event,
            body: value.chunks,
          })) {
            controller.enqueue(chunk);
          }
        },
      });

      const enqueueSubAgentToolEvent = (event: NocoBaseStreamEvent) => {
        const sessionId = event.sessionId;
        if (!sessionId) return;
        const chunks = toolCallsFromEvent(event);
        subAgentToolEvents.push(sessionId, {
          event,
          chunks,
          size: chunks.reduce(
            (size, chunk) =>
              size + (typeof chunk.args === 'string' ? chunk.args.length : 0),
            0,
          ),
        });
      };

      const enqueueVisualDelta = (chunk: BufferedVisualDelta) => {
        visualDeltas.push(`${chunk.type}:${chunk.id}`, chunk);
      };

      const subAgentNarrativeEvents = new StreamCoalescer<
        string,
        BufferedSubAgentEvent
      >({
        interval: VISUAL_DELTA_FLUSH_INTERVAL,
        maxSize: VISUAL_DELTA_FLUSH_SIZE,
        getSize: (value) => value.content.length,
        merge: (current, incoming) => ({
          event: incoming.event,
          content: `${current.content}${incoming.content}`,
        }),
        onFlush: (_, pending) => {
          const body =
            pending.event.type === 'reasoning' && isRecord(pending.event.body)
              ? { ...pending.event.body, content: pending.content }
              : pending.content;
          for (const chunk of subAgents.process({ ...pending.event, body })) {
            controller.enqueue(chunk);
          }
        },
      });

      const subAgentNarrativeKey = (sessionId: string, type: string) =>
        `${sessionId}:${type}`;

      const flushSubAgentNarrativeEvents = (sessionId?: string) => {
        if (!sessionId) {
          subAgentNarrativeEvents.flushAll();
          return;
        }
        subAgentNarrativeEvents.flush(
          subAgentNarrativeKey(sessionId, 'reasoning'),
        );
        subAgentNarrativeEvents.flush(
          subAgentNarrativeKey(sessionId, 'content'),
        );
      };

      const enqueueSubAgentNarrativeEvent = (event: NocoBaseStreamEvent) => {
        const sessionId = event.sessionId;
        if (!sessionId) return;
        const content =
          event.type === 'content' && typeof event.body === 'string'
            ? event.body
            : event.type === 'reasoning' && isRecord(event.body)
              ? typeof event.body.content === 'string'
                ? event.body.content
                : ''
              : '';
        if (!content) return;
        const otherType = event.type === 'content' ? 'reasoning' : 'content';
        subAgentNarrativeEvents.flush(
          subAgentNarrativeKey(sessionId, otherType),
        );
        subAgentNarrativeEvents.push(
          subAgentNarrativeKey(sessionId, event.type),
          { event, content },
        );
      };

      const finishActiveText = () => {
        if (!textStarted) return;
        visualDeltas.flush(`text-delta:${textId}`);
        controller.enqueue({ type: 'text-end', id: textId });
        textStarted = false;
        textId = `text-${crypto.randomUUID()}`;
      };

      const finishActiveReasoning = () => {
        if (!reasoningStarted) return;
        visualDeltas.flush(`reasoning-delta:${reasoningId}`);
        controller.enqueue({ type: 'reasoning-end', id: reasoningId });
        reasoningStarted = false;
        reasoningId = `reasoning-${crypto.randomUUID()}`;
      };

      const finishActiveNarrative = () => {
        finishActiveReasoning();
        finishActiveText();
      };

      try {
        for await (const event of parseNocoBaseSSE(stream)) {
          if (event.type !== 'tool_call_chunks') {
            toolInputDeltas.flushAll();
          }
          if (event.from === 'sub-agent') {
            finishActiveNarrative();
            if (event.type === 'content' || event.type === 'reasoning') {
              if (event.sessionId) subAgentToolEvents.flush(event.sessionId);
              enqueueSubAgentNarrativeEvent(event);
              continue;
            }
            flushSubAgentNarrativeEvents(event.sessionId);
            if (event.type === 'tool_call_chunks') {
              enqueueSubAgentToolEvent(event);
              continue;
            }
            if (event.sessionId) subAgentToolEvents.flush(event.sessionId);
            for (const chunk of subAgents.process(event)) {
              controller.enqueue(chunk);
            }
            continue;
          }

          flushSubAgentNarrativeEvents();
          subAgentToolEvents.flushAll();

          if (event.type === 'new_message') {
            responseStarted = true;
            continue;
          }

          if (!responseStarted && event.type !== 'error') {
            continue;
          }

          if (event.type === 'content' && typeof event.body === 'string') {
            finishActiveReasoning();
            if (!textStarted) {
              controller.enqueue({ type: 'text-start', id: textId });
              textStarted = true;
            }
            enqueueVisualDelta({
              type: 'text-delta',
              id: textId,
              delta: event.body,
            });
          }

          if (event.type === 'reasoning') {
            finishActiveText();
            const delta = reasoningContent(event);
            if (delta && !reasoningStarted) {
              controller.enqueue({
                type: 'reasoning-start',
                id: reasoningId,
              });
              reasoningStarted = true;
            }
            if (delta) {
              enqueueVisualDelta({
                type: 'reasoning-delta',
                id: reasoningId,
                delta,
              });
            }
          }

          if (event.type === 'tool_call_chunks') {
            finishActiveNarrative();
            for (const chunk of toolCallsFromEvent(event)) {
              const toolCallId = chunk.id ?? currentToolCallId;
              if (!toolCallId) continue;
              currentToolCallId = toolCallId;
              if (chunk.name && !announcedToolCalls.has(toolCallId)) {
                toolCallNames.set(toolCallId, chunk.name);
                controller.enqueue({
                  type: 'tool-input-start',
                  toolCallId,
                  toolName: chunk.name,
                  dynamic: true,
                });
                announcedToolCalls.add(toolCallId);
              }
              if (typeof chunk.args === 'string' && chunk.args) {
                const previousInput = toolCallInputs.get(toolCallId);
                toolCallInputs.set(
                  toolCallId,
                  `${typeof previousInput === 'string' ? previousInput : ''}${
                    chunk.args
                  }`,
                );
                toolInputDeltas.push(toolCallId, chunk.args);
              }
            }
          }

          if (event.type === 'tool_calls') {
            finishActiveNarrative();
            for (const toolCall of toolCallsFromEvent(event)) {
              const toolCallId = toolCall.id ?? `tool-${crypto.randomUUID()}`;
              const toolName = toolCall.name ?? 'tool';
              const toolState = getToolCallState(toolCall);
              const { invokeStatus, resultStatus } = toolState;
              const toolInput = parseToolInput(
                toolCall.args ?? toolCall.input ?? {},
              );
              toolCallNames.set(toolCallId, toolName);
              toolCallInputs.set(toolCallId, toolInput);
              controller.enqueue({
                type: 'tool-input-available',
                toolCallId,
                toolName,
                input: toolInput,
                providerMetadata: getToolProviderMetadata(toolCall),
                dynamic: true,
              });
              announcedToolCalls.add(toolCallId);

              if (toolState.failed) {
                controller.enqueue({
                  type: 'tool-output-error',
                  toolCallId,
                  errorText: toText(
                    toolCall.content ?? toolCall.output,
                    'Tool call failed',
                  ),
                  dynamic: true,
                });
              } else if (toolState.completed) {
                controller.enqueue({
                  type: 'tool-output-available',
                  toolCallId,
                  output: toolCall.output ??
                    toolCall.content ?? {
                      status: invokeStatus || resultStatus,
                    },
                  dynamic: true,
                });
              }
            }
          }

          if (event.type === 'tool_call_status' && isRecord(event.body)) {
            finishActiveNarrative();
            const toolCall = isRecord(event.body.toolCall)
              ? (event.body.toolCall as NocoBaseToolCall)
              : undefined;
            const toolCallId = toolCall?.id;
            if (toolCallId) {
              const mergedToolCall = {
                ...toolCall,
                invokeStatus:
                  typeof event.body.invokeStatus === 'string'
                    ? event.body.invokeStatus
                    : toolCall.invokeStatus,
                status:
                  typeof event.body.status === 'string'
                    ? event.body.status
                    : toolCall.status,
                content: event.body.content ?? toolCall.content,
              } satisfies NocoBaseToolCall;
              const toolState = getToolCallState(mergedToolCall);
              const { invokeStatus, resultStatus } = toolState;
              const toolName =
                toolCall.name ?? toolCallNames.get(toolCallId) ?? 'tool';
              const toolInput =
                toolCall.args !== undefined || toolCall.input !== undefined
                  ? parseToolInput(toolCall.args ?? toolCall.input)
                  : parseToolInput(toolCallInputs.get(toolCallId) ?? {});
              toolCallNames.set(toolCallId, toolName);
              toolCallInputs.set(toolCallId, toolInput);
              controller.enqueue({
                type: 'tool-input-available',
                toolCallId,
                toolName,
                input: toolInput,
                providerMetadata: getToolProviderMetadata(mergedToolCall),
                dynamic: true,
              });
              announcedToolCalls.add(toolCallId);
              if (toolState.failed) {
                controller.enqueue({
                  type: 'tool-output-error',
                  toolCallId,
                  errorText: toText(event.body.content, 'Tool call failed'),
                  dynamic: true,
                });
              } else if (toolState.completed) {
                controller.enqueue({
                  type: 'tool-output-available',
                  toolCallId,
                  output: event.body.content ?? {
                    status: invokeStatus || resultStatus,
                  },
                  dynamic: true,
                });
              }
            }
          }

          if (event.type === 'error') {
            controller.enqueue({
              type: 'error',
              errorText: toText(event.body, 'AI response failed'),
            });
          }
        }

        toolInputDeltas.flushAll();
        visualDeltas.flushAll();
        flushSubAgentNarrativeEvents();
        subAgentToolEvents.flushAll();
        finishActiveNarrative();
        controller.enqueue({ type: 'finish' });
        controller.close();
      } catch (error) {
        toolInputDeltas.clear();
        visualDeltas.clear();
        subAgentNarrativeEvents.clear();
        subAgentToolEvents.clear();
        controller.error(error);
      }
    },
  });
}

import type { Chat } from '@ai-sdk/react';
import { useCallback, useRef } from 'react';
import {
  getChatToolParts,
  getNocoBaseToolMetadata,
} from './chat-message-utils.js';
import type { AIChatMessage, AIToolCallDecision } from './types.js';

const isChatRunning = (chat: Chat<AIChatMessage>) =>
  chat.status === 'streaming' || chat.status === 'submitted';

export function useAutomaticToolApproval({
  enabled,
  decide,
}: {
  enabled: boolean;
  decide: (
    conversationId: string,
    targetChat: Chat<AIChatMessage>,
    decision: AIToolCallDecision,
    options?: { automatic?: boolean },
  ) => Promise<void>;
}) {
  const approvedRef = useRef(new Set<string>());
  const runningRef = useRef(new Set<string>());
  const rerunRef = useRef(new Set<string>());

  const process = useCallback(
    async (conversationId: string, targetChat: Chat<AIChatMessage>) => {
      if (!enabled || isChatRunning(targetChat)) return;
      if (runningRef.current.has(conversationId)) {
        rerunRef.current.add(conversationId);
        return;
      }

      runningRef.current.add(conversationId);
      try {
        do {
          rerunRef.current.delete(conversationId);
          const pending = getChatToolParts(targetChat.messages)
            .filter(
              ({ part }) => getNocoBaseToolMetadata(part)?.autoApprove === true,
            )
            .flatMap(({ message, part }) => {
              const key = `${conversationId}:${message.id}:${part.toolCallId}`;
              return approvedRef.current.has(key)
                ? []
                : [{ key, message, part }];
            });

          for (const { key, message, part } of pending) {
            approvedRef.current.add(key);
            try {
              await decide(
                conversationId,
                targetChat,
                {
                  messageId: message.id,
                  toolCallId: part.toolCallId,
                  toolName:
                    part.type === 'dynamic-tool'
                      ? part.toolName
                      : part.type.slice(5),
                  decision: 'approve',
                },
                { automatic: true },
              );
            } catch (error) {
              approvedRef.current.delete(key);
              throw error;
            }
          }
        } while (rerunRef.current.has(conversationId));
      } finally {
        runningRef.current.delete(conversationId);
        rerunRef.current.delete(conversationId);
      }
    },
    [decide, enabled],
  );

  const clearConversation = useCallback((conversationId: string) => {
    for (const key of approvedRef.current) {
      if (key.startsWith(`${conversationId}:`)) approvedRef.current.delete(key);
    }
    runningRef.current.delete(conversationId);
    rerunRef.current.delete(conversationId);
  }, []);

  const reset = useCallback(() => {
    approvedRef.current.clear();
    runningRef.current.clear();
    rerunRef.current.clear();
  }, []);

  return { clearConversation, process, reset };
}

import { useCallback, useEffect, useRef, useState } from 'react';
import { useAI } from './ai-context.js';
import type { AIChatAttachment } from './types.js';
import { toText } from '../shared/text.js';

const EMPTY_ATTACHMENTS: AIChatAttachment[] = [];

const disposeRemovedAttachmentPreviews = (
  current: AIChatAttachment[],
  next: AIChatAttachment[],
) => {
  const retainedPreviews = new Set(
    next.map((attachment) => attachment.preview).filter(Boolean),
  );
  for (const attachment of current) {
    if (
      attachment.preview?.startsWith('blob:') &&
      !retainedPreviews.has(attachment.preview)
    ) {
      URL.revokeObjectURL(attachment.preview);
    }
  }
};

const disposeAttachmentDrafts = (drafts: Record<string, AIChatAttachment[]>) =>
  Object.values(drafts).forEach((items) =>
    disposeRemovedAttachmentPreviews(items, []),
  );

export function useChatAttachments(activeConversationId: string) {
  const ai = useAI();
  const [drafts, setDrafts] = useState<Record<string, AIChatAttachment[]>>({});
  const draftsRef = useRef(drafts);
  draftsRef.current = drafts;

  const setConversationAttachments = useCallback(
    (
      conversationId: string,
      value:
        | AIChatAttachment[]
        | ((current: AIChatAttachment[]) => AIChatAttachment[]),
    ) => {
      setDrafts((current) => {
        const previous = current[conversationId] ?? [];
        const next = typeof value === 'function' ? value(previous) : value;
        disposeRemovedAttachmentPreviews(previous, next);
        return { ...current, [conversationId]: next };
      });
    },
    [],
  );

  const uploadFiles = useCallback(
    async (files: File[]) => {
      if (!files.length) return;
      const conversationId = activeConversationId;
      const pending = files.map((file) => ({
        uid: `upload-${crypto.randomUUID()}`,
        filename: file.name || `pasted-image-${Date.now()}`,
        status: 'uploading' as const,
        size: file.size,
        mimetype: file.type,
        preview: file.type.startsWith('image/')
          ? URL.createObjectURL(file)
          : undefined,
        progress: 0,
        file,
      }));
      setConversationAttachments(conversationId, (current) => [
        ...current,
        ...pending,
      ]);

      await Promise.all(
        pending.map(async (attachment) => {
          try {
            const response = await ai.uploadFile(attachment.file);
            const meta =
              response.meta && typeof response.meta === 'object'
                ? (response.meta as Record<string, unknown>)
                : undefined;
            const source =
              meta?.source && typeof meta.source === 'object'
                ? meta.source
                : response.source;
            setConversationAttachments(conversationId, (current) =>
              current.map((item) =>
                item.uid === attachment.uid
                  ? {
                      ...response,
                      uid: toText(response.id, attachment.uid),
                      filename: toText(
                        response.filename ?? response.title,
                        attachment.filename,
                      ),
                      status: 'done',
                      size:
                        typeof response.size === 'number'
                          ? response.size
                          : attachment.size,
                      mimetype:
                        typeof response.mimetype === 'string'
                          ? response.mimetype
                          : attachment.mimetype,
                      url:
                        typeof response.url === 'string'
                          ? response.url
                          : undefined,
                      preview:
                        typeof response.preview === 'string'
                          ? response.preview
                          : attachment.mimetype?.startsWith('image/') &&
                              typeof response.url === 'string'
                            ? response.url
                            : attachment.preview,
                      progress: 100,
                      source,
                    }
                  : item,
              ),
            );
          } catch (error) {
            setConversationAttachments(conversationId, (current) =>
              current.map((item) =>
                item.uid === attachment.uid
                  ? {
                      ...item,
                      status: 'error',
                      error:
                        error instanceof Error
                          ? error.message
                          : 'File upload failed',
                    }
                  : item,
              ),
            );
          }
        }),
      );
    },
    [activeConversationId, ai, setConversationAttachments],
  );

  const removeAttachment = useCallback(
    (uid: string) => {
      setConversationAttachments(activeConversationId, (current) => {
        return current.filter((attachment) => attachment.uid !== uid);
      });
    },
    [activeConversationId, setConversationAttachments],
  );

  const moveAttachments = useCallback((from: string, to: string) => {
    setDrafts((current) => {
      if (!current[from]) return current;
      const next = { ...current, [to]: current[from] };
      delete next[from];
      return next;
    });
  }, []);

  const removeConversationAttachments = useCallback(
    (conversationId: string) => {
      setDrafts((current) => {
        if (!current[conversationId]) return current;
        disposeRemovedAttachmentPreviews(current[conversationId], []);
        const next = { ...current };
        delete next[conversationId];
        return next;
      });
    },
    [],
  );

  const clearAttachments = useCallback(
    () =>
      setDrafts((current) => {
        disposeAttachmentDrafts(current);
        return {};
      }),
    [],
  );
  // Falls back to the shared EMPTY_ATTACHMENTS rather than a fresh `[]`: callers compare the
  // result by identity across an await to detect "the user changed the attachments mid-send", and
  // a new array each call would make that check fire on every send from a conversation with no
  // attachments.
  const getConversationAttachments = useCallback(
    (conversationId: string) =>
      draftsRef.current[conversationId] ?? EMPTY_ATTACHMENTS,
    [],
  );
  const attachments = drafts[activeConversationId] ?? EMPTY_ATTACHMENTS;

  useEffect(() => () => disposeAttachmentDrafts(draftsRef.current), []);

  return {
    attachments,
    uploadingAttachments: attachments.some(
      (attachment) => attachment.status === 'uploading',
    ),
    uploadFiles,
    removeAttachment,
    setConversationAttachments,
    moveAttachments,
    removeConversationAttachments,
    clearAttachments,
    getConversationAttachments,
  };
}

import type { Chat } from '@ai-sdk/react';
import {
  useCallback,
  type Dispatch,
  type MutableRefObject,
  type SetStateAction,
} from 'react';
import type { AIChatAction, AIChatState } from './chat-reducer.js';
import { findChatMessage, isAIToolPart } from './chat-message-utils.js';
import { getAIWorkContextToolScope } from './page-context-utils.js';
import type { NocoBaseChatTransport } from './chat-transport.js';
import type { useAI } from './ai-context.js';
import type { AIConversationRuntimeContext } from './use-chat-runtime.js';
import { useAutomaticToolApproval } from './use-automatic-tool-approval.js';
import type {
  AIChatAttachment,
  AIChatMessage,
  AIToolCallDecision,
  AIToolCallInvocationContext,
  AIWorkContextItem,
} from './types.js';

type AIContextValue = ReturnType<typeof useAI>;

export type AIMessageEditingSnapshot = {
  conversationId: string;
  messages: AIChatMessage[];
  attachments: AIChatAttachment[];
  workContext: AIWorkContextItem[];
};

type RefreshConversationMessages = (
  conversationId: string,
  targetChat: Chat<AIChatMessage>,
  options?: { updateRead?: boolean },
) => Promise<AIChatMessage[]>;

const isChatRunning = (chat: Chat<AIChatMessage>) =>
  chat.status === 'streaming' || chat.status === 'submitted';

const getToolInvocationContext = ({
  conversationId,
  messages,
  rootIndex,
  runtimeContext,
  messageId,
  toolCallId,
  toolName,
  automatic,
}: {
  conversationId: string;
  messages: AIChatMessage[];
  rootIndex: number;
  runtimeContext: AIConversationRuntimeContext;
  messageId: string;
  toolCallId: string;
  toolName: string;
  automatic?: boolean;
}): AIToolCallInvocationContext => {
  const userContext = messages
    .slice(0, rootIndex + 1)
    .reverse()
    .find((message) => message.role === 'user')?.metadata?.workContext;
  return {
    sessionId: conversationId,
    messageId,
    toolCallId,
    toolName,
    automatic,
    ...getAIWorkContextToolScope([
      ...(runtimeContext.task?.workContext ?? []),
      ...(userContext ?? []),
    ]),
  };
};

export function useChatMessageActions({
  ai,
  activeChat,
  getChat,
  stateRef,
  chatSurfaceOpenRef,
  transportsRef,
  getRuntimeContext,
  refreshConversationMessages,
  setHistoryError,
  editingSnapshotRef,
  setEditingMessageId,
  getConversationAttachments,
  getConversationWorkContext,
  setConversationAttachments,
  setConversationWorkContext,
  dispatch,
  requestComposerFocus,
}: {
  ai: AIContextValue;
  activeChat: Chat<AIChatMessage>;
  getChat: (conversationId: string) => Chat<AIChatMessage>;
  stateRef: MutableRefObject<AIChatState>;
  chatSurfaceOpenRef: MutableRefObject<boolean>;
  transportsRef: MutableRefObject<Map<string, NocoBaseChatTransport>>;
  getRuntimeContext: (conversationId: string) => AIConversationRuntimeContext;
  refreshConversationMessages: RefreshConversationMessages;
  setHistoryError: Dispatch<SetStateAction<Error | undefined>>;
  editingSnapshotRef: MutableRefObject<AIMessageEditingSnapshot | undefined>;
  setEditingMessageId: Dispatch<SetStateAction<string | undefined>>;
  getConversationAttachments: (conversationId: string) => AIChatAttachment[];
  getConversationWorkContext: (conversationId: string) => AIWorkContextItem[];
  setConversationAttachments: (
    conversationId: string,
    attachments: AIChatAttachment[],
  ) => void;
  setConversationWorkContext: (
    conversationId: string,
    context: AIWorkContextItem[],
  ) => void;
  dispatch: Dispatch<AIChatAction>;
  requestComposerFocus: () => void;
}) {
  const resolveServerMessage = useCallback(
    async (
      conversationId: string,
      targetChat: Chat<AIChatMessage>,
      message: AIChatMessage,
    ) => {
      let messages = targetChat.messages;
      const resolvedMessage = findChatMessage(messages, message.id);
      if (!resolvedMessage) {
        throw new Error(
          'The message is no longer available in this conversation.',
        );
      }
      let { targetMessage, rootIndex } = resolvedMessage;

      if (!targetMessage.metadata?.serverMessageId) {
        messages = await refreshConversationMessages(
          conversationId,
          targetChat,
          {
            updateRead:
              stateRef.current.activeConversationId === conversationId &&
              chatSurfaceOpenRef.current,
          },
        );
        const refreshedMatch = findChatMessage(messages, message.id);
        const refreshedTarget = refreshedMatch?.targetMessage;
        if (!refreshedTarget) {
          throw new Error(
            'Unable to resolve the server message for this action.',
          );
        }
        targetMessage = refreshedTarget;
        rootIndex = refreshedMatch.rootIndex;
      }

      return {
        conversationId,
        messages,
        targetMessage,
        rootIndex,
        serverMessageId: targetMessage.metadata?.serverMessageId,
      };
    },
    [chatSurfaceOpenRef, refreshConversationMessages, stateRef],
  );

  const retryMessage = useCallback(
    async (message: AIChatMessage) => {
      if (
        message.role !== 'assistant' ||
        activeChat.status === 'streaming' ||
        activeChat.status === 'submitted'
      ) {
        return;
      }

      setHistoryError(undefined);
      try {
        const resolved = await resolveServerMessage(
          stateRef.current.activeConversationId,
          activeChat,
          message,
        );
        if (!resolved.serverMessageId) {
          throw new Error('The server message id is unavailable for retry.');
        }
        const transport = transportsRef.current.get(resolved.conversationId);
        if (!transport) {
          throw new Error('The NocoBase chat transport is unavailable.');
        }
        transport.prepareResend(resolved.serverMessageId);
        try {
          await activeChat.regenerate({ messageId: resolved.targetMessage.id });
        } catch (error) {
          transport.cancelResend(resolved.serverMessageId);
          throw error;
        }
      } catch (error) {
        setHistoryError(
          error instanceof Error ? error : new Error('Unable to retry message'),
        );
      }
    },
    [
      activeChat,
      resolveServerMessage,
      setHistoryError,
      stateRef,
      transportsRef,
    ],
  );

  const decideConversationToolCall = useCallback(
    async (
      conversationId: string,
      targetChat: Chat<AIChatMessage>,
      decision: AIToolCallDecision,
      options: { automatic?: boolean } = {},
    ) => {
      if (isChatRunning(targetChat)) return;

      setHistoryError(undefined);
      try {
        const message = findChatMessage(
          targetChat.messages,
          decision.messageId,
        )?.targetMessage;
        if (!message) {
          throw new Error('The tool-call message is no longer available.');
        }
        const resolved = await resolveServerMessage(
          conversationId,
          targetChat,
          message,
        );
        if (!resolved.serverMessageId) {
          throw new Error(
            'The server message id is unavailable for this tool decision.',
          );
        }
        const toolPart = resolved.targetMessage.parts
          .filter(isAIToolPart)
          .find((part) => part.toolCallId === decision.toolCallId);
        const toolName =
          toolPart?.type === 'dynamic-tool'
            ? toolPart.toolName
            : toolPart?.type.startsWith('tool-')
              ? toolPart.type.slice(5)
              : decision.toolName;
        const runtimeContext = getRuntimeContext(resolved.conversationId);
        const invocationContext = getToolInvocationContext({
          conversationId: resolved.conversationId,
          messages: resolved.messages,
          rootIndex: resolved.rootIndex,
          runtimeContext,
          messageId: resolved.serverMessageId,
          toolCallId: decision.toolCallId,
          toolName,
          automatic: options.automatic,
        });
        if (
          options.automatic &&
          !ai.canAutoApproveToolCall(
            toolName,
            toolPart?.input ?? decision.input,
            invocationContext,
          )
        ) {
          if (toolPart && 'callProviderMetadata' in toolPart) {
            const providerMetadata = toolPart.callProviderMetadata ?? {};
            const nocobase =
              providerMetadata.nocobase &&
              typeof providerMetadata.nocobase === 'object'
                ? providerMetadata.nocobase
                : {};
            toolPart.callProviderMetadata = {
              ...providerMetadata,
              nocobase: {
                ...nocobase,
                autoApprove: false,
                requiresApproval: true,
              },
            };
            targetChat.messages = [...targetChat.messages];
          }
          return;
        }
        const userDecision =
          decision.decision === 'approve'
            ? ({ type: 'approve' } as const)
            : decision.decision === 'reject'
              ? ({
                  type: 'reject',
                  ...(typeof decision.input === 'string'
                    ? { message: decision.input }
                    : {}),
                } as const)
              : ({
                  type: 'edit',
                  editedAction: { name: toolName, args: decision.input },
                } as const);
        const result = await ai.updateToolCallDecision({
          sessionId: resolved.conversationId,
          messageId: resolved.serverMessageId,
          toolCallId: decision.toolCallId,
          userDecision,
        });
        if (!result.updated) {
          await refreshConversationMessages(
            resolved.conversationId,
            targetChat,
            {
              updateRead:
                stateRef.current.activeConversationId ===
                  resolved.conversationId && chatSurfaceOpenRef.current,
            },
          );
          return;
        }

        const interruptingToolCalls = result.toolCalls.filter(
          (toolCall) =>
            toolCall.willInterrupt === true ||
            toolCall.execution === 'frontend' ||
            toolCall.auto === false,
        );
        const allWaiting =
          interruptingToolCalls.length > 0 &&
          interruptingToolCalls.every(
            (toolCall) =>
              String(toolCall.invokeStatus).toLowerCase() === 'waiting',
          );
        if (!allWaiting) return;

        const toolCallIds = result.toolCalls.map((toolCall) => toolCall.id);
        const toolCallResults: Array<{ id: string; result: unknown }> = [];
        for (const toolCall of result.toolCalls) {
          const invocation = await ai.invokeToolCall(
            toolCall.name,
            toolCall.args,
            {
              ...invocationContext,
              toolCallId: toolCall.id,
              toolName: toolCall.name,
            },
          );
          if (invocation.handled) {
            toolCallResults.push({
              id: toolCall.id,
              result: invocation.result,
            });
          }
        }

        const transport = transportsRef.current.get(resolved.conversationId);
        if (!transport) {
          throw new Error('The NocoBase chat transport is unavailable.');
        }
        if (resolved.rootIndex !== targetChat.messages.length - 1) {
          targetChat.messages = resolved.messages.slice(
            0,
            resolved.rootIndex + 1,
          );
        }
        const responseMessageId = `assistant-${crypto.randomUUID()}`;
        targetChat.messages = [
          ...targetChat.messages,
          {
            id: responseMessageId,
            role: 'assistant',
            metadata: {
              createdAt: new Date().toISOString(),
              employeeUsername: runtimeContext.employeeUsername,
            },
            parts: [],
          },
        ];
        transport.prepareToolResume(
          resolved.serverMessageId,
          responseMessageId,
          toolCallIds,
          toolCallResults,
        );
        try {
          await targetChat.resumeStream();
        } catch (error) {
          transport.cancelToolResume(resolved.serverMessageId);
          targetChat.messages = targetChat.messages.filter(
            (item) => item.id !== responseMessageId,
          );
          throw error;
        }
      } catch (error) {
        setHistoryError(
          error instanceof Error
            ? error
            : new Error('Unable to process the tool decision'),
        );
        throw error;
      }
    },
    [
      ai,
      chatSurfaceOpenRef,
      getRuntimeContext,
      refreshConversationMessages,
      resolveServerMessage,
      setHistoryError,
      stateRef,
      transportsRef,
    ],
  );

  const decideToolCall = useCallback(
    (decision: AIToolCallDecision) =>
      decideConversationToolCall(
        stateRef.current.activeConversationId,
        activeChat,
        decision,
      ),
    [activeChat, decideConversationToolCall, stateRef],
  );

  const {
    clearConversation: clearAutomaticToolApproval,
    process: processAutomaticToolApprovals,
  } = useAutomaticToolApproval({
    enabled: true,
    decide: decideConversationToolCall,
  });

  const startEditingMessage = useCallback(
    async (message: AIChatMessage) => {
      if (
        message.role !== 'user' ||
        activeChat.status === 'streaming' ||
        activeChat.status === 'submitted'
      ) {
        return;
      }
      let messages = activeChat.messages;
      let targetMessage = message;
      let index = messages.findIndex((item) => item.id === message.id);
      if (index < 0) return;
      const conversationId = stateRef.current.activeConversationId;
      if (!message.metadata?.serverMessageId) {
        const userMessageIndex =
          messages.slice(0, index + 1).filter((item) => item.role === 'user')
            .length - 1;
        try {
          messages = await refreshConversationMessages(
            conversationId,
            activeChat,
            { updateRead: true },
          );
        } catch (error) {
          setHistoryError(
            error instanceof Error
              ? error
              : new Error('Unable to refresh conversation messages'),
          );
          return;
        }
        if (stateRef.current.activeConversationId !== conversationId) return;
        targetMessage = messages.filter((item) => item.role === 'user')[
          userMessageIndex
        ];
        if (!targetMessage?.metadata?.serverMessageId) return;
        index = messages.findIndex((item) => item.id === targetMessage.id);
        if (index < 0) return;
      }
      const serverMessageId = targetMessage.metadata?.serverMessageId;
      editingSnapshotRef.current = {
        conversationId,
        messages: [...messages],
        attachments: getConversationAttachments(conversationId),
        workContext: getConversationWorkContext(conversationId),
      };
      setEditingMessageId(serverMessageId ?? targetMessage.id);
      // Resolve the chat here rather than mutating the one this render closed
      // over: the store write belongs to the callback, not to the render.
      getChat(conversationId).messages = messages.slice(0, index);
      setConversationAttachments(
        conversationId,
        targetMessage.metadata?.attachments ?? [],
      );
      setConversationWorkContext(
        conversationId,
        targetMessage.metadata?.workContext ?? [],
      );
      dispatch({
        type: 'set-draft',
        conversationId,
        value: targetMessage.parts
          .filter((part) => part.type === 'text')
          .map((part) => part.text)
          .join('\n'),
      });
      requestComposerFocus();
    },
    [
      activeChat,
      dispatch,
      editingSnapshotRef,
      getChat,
      getConversationAttachments,
      getConversationWorkContext,
      refreshConversationMessages,
      requestComposerFocus,
      setConversationAttachments,
      setConversationWorkContext,
      setEditingMessageId,
      setHistoryError,
      stateRef,
    ],
  );

  const cancelEditingMessage = useCallback(() => {
    const snapshot = editingSnapshotRef.current;
    if (
      snapshot &&
      snapshot.conversationId === stateRef.current.activeConversationId
    ) {
      getChat(snapshot.conversationId).messages = snapshot.messages;
      setConversationAttachments(snapshot.conversationId, snapshot.attachments);
      setConversationWorkContext(snapshot.conversationId, snapshot.workContext);
      dispatch({
        type: 'set-draft',
        conversationId: snapshot.conversationId,
        value: '',
      });
    }
    setEditingMessageId(undefined);
    editingSnapshotRef.current = undefined;
  }, [
    dispatch,
    editingSnapshotRef,
    getChat,
    setConversationAttachments,
    setConversationWorkContext,
    setEditingMessageId,
    stateRef,
  ]);

  return {
    retryMessage,
    decideToolCall,
    startEditingMessage,
    cancelEditingMessage,
    clearAutomaticToolApproval,
    processAutomaticToolApprovals,
  };
}

import { Chat } from '@ai-sdk/react';
import {
  useCallback,
  useEffect,
  useRef,
  type Dispatch,
  type MutableRefObject,
} from 'react';
import type { AIChatAction, AIChatState } from './chat-reducer.js';
import { NocoBaseChatTransport } from './chat-transport.js';
import { getAIModelKey, resolveEmployeeModel } from './model.js';
import type { useAI } from './ai-context.js';
import {
  AI_DRAFT_CONVERSATION_ID,
  type AIChatMessage,
  type AIChatTaskRuntime,
} from './types.js';

type AIContextValue = ReturnType<typeof useAI>;

export type AIConversationRuntimeContext = {
  employeeUsername: string;
  model: string;
  task?: AIChatTaskRuntime;
};

export function useChatRuntime({
  id,
  ai,
  stateRef,
  taskRuntimeRef,
  webSearchRef,
  conversationFinishedHandlerRef,
  moveAttachments,
  moveWorkContext,
  dispatch,
}: {
  id: string;
  ai: AIContextValue;
  stateRef: MutableRefObject<AIChatState>;
  taskRuntimeRef: MutableRefObject<AIChatTaskRuntime | undefined>;
  webSearchRef: MutableRefObject<boolean>;
  conversationFinishedHandlerRef: MutableRefObject<
    | ((conversationId: string, chat: Chat<AIChatMessage>) => Promise<void>)
    | undefined
  >;
  moveAttachments: (from: string, to: string) => void;
  moveWorkContext: (from: string, to: string) => void;
  dispatch: Dispatch<AIChatAction>;
}) {
  // A chat is created once and cached, and its transport asks for the context
  // on every send. Reading the configuration through a ref keeps a chat made
  // before the employees and models loaded from sending with empty lists.
  const aiRef = useRef(ai);
  useEffect(() => {
    aiRef.current = ai;
  }, [ai]);
  const chatsRef = useRef(new Map<string, Chat<AIChatMessage>>());
  const transportsRef = useRef(new Map<string, NocoBaseChatTransport>());
  const runtimeContextsRef = useRef(
    new Map<string, AIConversationRuntimeContext>(),
  );

  const getRuntimeContext = useCallback(
    (conversationId: string): AIConversationRuntimeContext => {
      const existing = runtimeContextsRef.current.get(conversationId);
      if (existing) return existing;

      const latestState = stateRef.current;
      const conversation = latestState.conversations.find(
        (item) => item.id === conversationId,
      );
      const conversationModel = conversation?.model
        ? ai.models.find(
            (item) =>
              item.value === conversation.model?.model &&
              (!conversation.model.llmService ||
                item.llmService === conversation.model.llmService),
          )
        : undefined;
      const context = {
        employeeUsername:
          conversation?.employeeUsername ??
          latestState.selectedEmployeeUsername,
        model: conversationModel
          ? getAIModelKey(conversationModel)
          : latestState.selectedModel,
        task:
          conversationId === AI_DRAFT_CONVERSATION_ID
            ? taskRuntimeRef.current
            : undefined,
      };
      runtimeContextsRef.current.set(conversationId, context);
      return context;
    },
    [ai.models, stateRef, taskRuntimeRef],
  );

  const getChat = useCallback(
    (conversationId: string) => {
      const existing = chatsRef.current.get(conversationId);
      if (existing) return existing;

      let runtimeConversationId = conversationId;
      const transport = ai.createTransport({
        chatId: `${id}:${conversationId}`,
        getContext: () => {
          const runtimeContext = getRuntimeContext(runtimeConversationId);
          const { employees, models } = aiRef.current;
          const employee =
            employees.find(
              (item) => item.username === runtimeContext.employeeUsername,
            ) ?? employees[0];
          const model = resolveEmployeeModel(
            models,
            employee,
            runtimeContext.model,
          );
          if (!employee || !model) {
            throw new Error(
              'AIProvider requires at least one employee and model',
            );
          }
          const task = runtimeContext.task;
          return {
            sessionId:
              runtimeConversationId === AI_DRAFT_CONVERSATION_ID
                ? undefined
                : runtimeConversationId,
            employee,
            model,
            task: task
              ? {
                  ...task,
                  webSearch: task.webSearch ?? webSearchRef.current,
                }
              : webSearchRef.current
                ? { workContext: [], webSearch: true }
                : undefined,
          };
        },
        onSessionCreated: (sessionId) => {
          const previousConversationId = runtimeConversationId;
          chatsRef.current.delete(runtimeConversationId);
          chatsRef.current.set(sessionId, chat);
          if (transport instanceof NocoBaseChatTransport) {
            transportsRef.current.delete(previousConversationId);
            transportsRef.current.set(sessionId, transport);
          }
          const runtimeContext = runtimeContextsRef.current.get(
            previousConversationId,
          );
          if (runtimeContext) {
            runtimeContextsRef.current.delete(previousConversationId);
            runtimeContextsRef.current.set(sessionId, runtimeContext);
          }
          moveAttachments(previousConversationId, sessionId);
          moveWorkContext(previousConversationId, sessionId);
          dispatch({
            type: 'replace-conversation-id',
            from: runtimeConversationId,
            to: sessionId,
          });
          runtimeConversationId = sessionId;
        },
      });
      const chat = new Chat<AIChatMessage>({
        id: `${id}:${conversationId}`,
        messages: [],
        onFinish: () => {
          const finishedConversationId = runtimeConversationId;
          if (finishedConversationId === AI_DRAFT_CONVERSATION_ID) {
            return;
          }
          queueMicrotask(() => {
            void conversationFinishedHandlerRef.current?.(
              finishedConversationId,
              chat,
            );
          });
        },
        transport,
      });
      chatsRef.current.set(conversationId, chat);
      if (transport instanceof NocoBaseChatTransport) {
        transportsRef.current.set(conversationId, transport);
      }
      return chat;
    },
    [
      ai,
      conversationFinishedHandlerRef,
      dispatch,
      getRuntimeContext,
      id,
      moveAttachments,
      moveWorkContext,
      webSearchRef,
    ],
  );

  const getTransport = useCallback(
    (conversationId: string) => transportsRef.current.get(conversationId),
    [],
  );

  const remove = useCallback((conversationId: string) => {
    chatsRef.current.delete(conversationId);
    transportsRef.current.delete(conversationId);
    runtimeContextsRef.current.delete(conversationId);
  }, []);

  return {
    chatsRef,
    transportsRef,
    runtimeContextsRef,
    getRuntimeContext,
    getChat,
    getTransport,
    remove,
  };
}

import type { Chat } from '@ai-sdk/react';
import type { UIMessage } from 'ai';
import { useCallback, useSyncExternalStore } from 'react';

const MESSAGE_THROTTLE_MS = 32;

export function useChatState<CHAT_MESSAGE extends UIMessage>(
  chat: Chat<CHAT_MESSAGE>,
) {
  // The throttle the Chat offers keeps its pending notification when the
  // subscription ends, so a message update that lands just before an unmount
  // still reaches React afterwards. Throttling here lets unsubscribing cancel it.
  const subscribeToMessages = useCallback(
    (onStoreChange: () => void) => {
      let timer: ReturnType<typeof setTimeout> | undefined;
      let lastNotifiedAt = 0;
      const notify = () => {
        timer = undefined;
        lastNotifiedAt = Date.now();
        onStoreChange();
      };
      const unsubscribe = chat['~registerMessagesCallback'](() => {
        clearTimeout(timer);
        const wait = MESSAGE_THROTTLE_MS - (Date.now() - lastNotifiedAt);
        if (wait <= 0) notify();
        else timer = setTimeout(notify, wait);
      });
      return () => {
        clearTimeout(timer);
        unsubscribe();
      };
    },
    [chat],
  );
  const subscribeToStatus = useCallback(
    (onStoreChange: () => void) =>
      chat['~registerStatusCallback'](onStoreChange),
    [chat],
  );
  const subscribeToError = useCallback(
    (onStoreChange: () => void) =>
      chat['~registerErrorCallback'](onStoreChange),
    [chat],
  );
  const getMessages = useCallback(() => chat.messages, [chat]);
  const getStatus = useCallback(() => chat.status, [chat]);
  const getError = useCallback(() => chat.error, [chat]);

  return {
    messages: useSyncExternalStore(
      subscribeToMessages,
      getMessages,
      getMessages,
    ),
    status: useSyncExternalStore(subscribeToStatus, getStatus, getStatus),
    error: useSyncExternalStore(subscribeToError, getError, getError),
  };
}

import { useCallback, useEffect, useRef, useState } from 'react';
import type { AIWorkContextItem } from './types.js';

const EMPTY_CONTEXT: AIWorkContextItem[] = [];

const contextItemKey = (item: AIWorkContextItem) =>
  `${item.type}:${item.id ?? item.title ?? 'context'}`;

export function useChatWorkContext(activeConversationId: string) {
  const [drafts, setDrafts] = useState<Record<string, AIWorkContextItem[]>>({});
  const draftsRef = useRef(drafts);
  useEffect(() => {
    draftsRef.current = drafts;
  }, [drafts]);

  const setConversationWorkContext = useCallback(
    (
      conversationId: string,
      value:
        | AIWorkContextItem[]
        | ((current: AIWorkContextItem[]) => AIWorkContextItem[]),
    ) => {
      setDrafts((current) => ({
        ...current,
        [conversationId]:
          typeof value === 'function'
            ? value(current[conversationId] ?? [])
            : value,
      }));
    },
    [],
  );

  const addWorkContext = useCallback(
    (item: AIWorkContextItem) => {
      setConversationWorkContext(activeConversationId, (current) => {
        const key = contextItemKey(item);
        return [
          ...current.filter((entry) => contextItemKey(entry) !== key),
          item,
        ];
      });
    },
    [activeConversationId, setConversationWorkContext],
  );

  const removeWorkContext = useCallback(
    (item: AIWorkContextItem) => {
      const key = contextItemKey(item);
      setConversationWorkContext(activeConversationId, (current) =>
        current.filter((entry) => contextItemKey(entry) !== key),
      );
    },
    [activeConversationId, setConversationWorkContext],
  );

  const moveWorkContext = useCallback((from: string, to: string) => {
    setDrafts((current) => {
      if (!current[from]) return current;
      const next = { ...current, [to]: current[from] };
      delete next[from];
      return next;
    });
  }, []);

  const removeConversationWorkContext = useCallback(
    (conversationId: string) => {
      setDrafts((current) => {
        if (!current[conversationId]) return current;
        const next = { ...current };
        delete next[conversationId];
        return next;
      });
    },
    [],
  );

  const clearWorkContext = useCallback(() => setDrafts({}), []);
  // Shared EMPTY_CONTEXT rather than a fresh `[]` — see getConversationAttachments: the send path
  // compares this by identity across an await, so a new array each call would read as "the user
  // changed the work context" and silently abort every send.
  const getConversationWorkContext = useCallback(
    (conversationId: string) =>
      draftsRef.current[conversationId] ?? EMPTY_CONTEXT,
    [],
  );
  const workContext = drafts[activeConversationId] ?? EMPTY_CONTEXT;

  return {
    workContext,
    addWorkContext,
    removeWorkContext,
    setConversationWorkContext,
    moveWorkContext,
    removeConversationWorkContext,
    clearWorkContext,
    getConversationWorkContext,
  };
}

import { useCallback, useEffect, useRef, useState } from 'react';
import type { AIConfigurationStatus, AIConversation } from './types.js';

export function useConversationCatalog({
  configurationStatus,
  listConversations,
  onChange,
  onError,
}: {
  configurationStatus: AIConfigurationStatus;
  listConversations: (keyword?: string) => Promise<AIConversation[]>;
  onChange: (conversations: AIConversation[]) => void;
  onError: (error?: Error) => void;
}) {
  const [searching, setSearching] = useState(false);
  const [initialLoaded, setInitialLoaded] = useState(false);
  const [search, setSearch] = useState('');
  // Derived rather than toggled from the effect below: the catalog is loading
  // from the moment the configuration is ready until the first list resolves.
  const loading =
    searching || (configurationStatus === 'ready' && !initialLoaded);
  const searchRef = useRef('');
  const requestRef = useRef(0);
  const catalogRef = useRef<AIConversation[]>([]);

  const apply = useCallback(
    (conversations: AIConversation[], keyword = searchRef.current) => {
      if (!keyword) catalogRef.current = conversations;
      onChange(conversations);
    },
    [onChange],
  );

  const refresh = useCallback(async () => {
    const requestId = requestRef.current + 1;
    requestRef.current = requestId;
    const keyword = searchRef.current;
    const conversations = await listConversations(keyword);
    if (requestRef.current === requestId) apply(conversations, keyword);
    return conversations;
  }, [apply, listConversations]);

  useEffect(() => {
    if (configurationStatus !== 'ready') return;
    let active = true;
    onError(undefined);
    void listConversations()
      .then((conversations) => {
        if (!active || searchRef.current) return;
        apply(conversations, '');
      })
      .catch((error: unknown) => {
        if (!active) return;
        onError(
          error instanceof Error
            ? error
            : new Error('Unable to load conversations'),
        );
      })
      .finally(() => {
        if (active) setInitialLoaded(true);
      });
    return () => {
      active = false;
    };
  }, [apply, configurationStatus, listConversations, onError]);

  const searchConversations = useCallback(
    async (keyword: string) => {
      const normalizedKeyword = keyword.trim();
      setSearch(keyword);
      searchRef.current = normalizedKeyword;

      const requestId = requestRef.current + 1;
      requestRef.current = requestId;
      setSearching(true);
      onError(undefined);
      try {
        const conversations = await listConversations(normalizedKeyword);
        if (requestRef.current !== requestId) return;
        apply(conversations, normalizedKeyword);
      } catch (error) {
        if (requestRef.current !== requestId) return;
        const resolvedError =
          error instanceof Error
            ? error
            : new Error('Unable to search conversations');
        onError(resolvedError);
        throw resolvedError;
      } finally {
        if (requestRef.current === requestId) setSearching(false);
      }
    },
    [apply, listConversations, onError],
  );

  const updateCatalog = useCallback(
    (updater: (conversations: AIConversation[]) => AIConversation[]) => {
      catalogRef.current = updater(catalogRef.current);
    },
    [],
  );

  return {
    loading,
    search,
    searchRef,
    refresh,
    searchConversations,
    updateCatalog,
  };
}

import type { Chat } from '@ai-sdk/react';
import { useCallback, useEffect, useRef, useState } from 'react';
import type { NocoBaseChatTransport } from './chat-transport.js';
import { reconcileRefreshedMessages } from './chat-message-utils.js';
import { AI_DRAFT_CONVERSATION_ID, type AIChatMessage } from './types.js';

const isChatRunning = (chat: Chat<AIChatMessage>) =>
  chat.status === 'streaming' || chat.status === 'submitted';

export function useConversationHistory({
  chatSurfaceOpen,
  activeConversationId,
  getActiveConversationId,
  getChat,
  getTransport,
  getConversationMessages,
  getConversationActiveState,
  onMarkRead,
  onError,
}: {
  chatSurfaceOpen: boolean;
  activeConversationId: string;
  getActiveConversationId: () => string;
  getChat: (conversationId: string) => Chat<AIChatMessage>;
  getTransport: (conversationId: string) => NocoBaseChatTransport | undefined;
  getConversationMessages: (
    conversationId: string,
    options?: { updateRead?: boolean },
  ) => Promise<AIChatMessage[]>;
  getConversationActiveState: (
    conversationId: string,
  ) => Promise<string | undefined>;
  onMarkRead: (conversationId: string) => void;
  onError: (error?: Error) => void;
}) {
  const surfaceOpenRef = useRef(chatSurfaceOpen);
  const openVersionRef = useRef(0);
  const pendingRequestsRef = useRef(
    new Map<string, Promise<AIChatMessage[]>>(),
  );
  const [loadingId, setLoadingId] = useState<string>();
  useEffect(() => {
    surfaceOpenRef.current = chatSurfaceOpen;
  }, [chatSurfaceOpen]);

  const refresh = useCallback(
    (
      conversationId: string,
      targetChat: Chat<AIChatMessage>,
      options: { updateRead?: boolean } = {},
    ) => {
      const updateRead = options.updateRead === true;
      const requestKey = `${conversationId}:${updateRead ? 'read' : 'peek'}`;
      const pending = pendingRequestsRef.current.get(requestKey);
      if (pending) return pending;

      const request = getConversationMessages(conversationId, { updateRead })
        .then((messages) => {
          const reconciled = reconcileRefreshedMessages(
            targetChat.messages,
            messages,
          );
          targetChat.messages = reconciled;
          return reconciled;
        })
        .finally(() => pendingRequestsRef.current.delete(requestKey));
      pendingRequestsRef.current.set(requestKey, request);
      return request;
    },
    [getConversationMessages],
  );

  const load = useCallback(
    async (conversationId: string) => {
      const targetChat = getChat(conversationId);
      if (isChatRunning(targetChat)) return;

      const openVersion = openVersionRef.current + 1;
      openVersionRef.current = openVersion;
      setLoadingId(conversationId);
      onError(undefined);
      try {
        await refresh(conversationId, targetChat, { updateRead: true });
        onMarkRead(conversationId);
      } catch (error) {
        onError(
          error instanceof Error
            ? error
            : new Error('Unable to load conversation messages'),
        );
        return;
      } finally {
        setLoadingId((current) =>
          current === conversationId ? undefined : current,
        );
      }

      if (
        openVersionRef.current !== openVersion ||
        getActiveConversationId() !== conversationId ||
        isChatRunning(targetChat)
      ) {
        return;
      }

      try {
        const activeState = await getConversationActiveState(conversationId);
        if (
          openVersionRef.current !== openVersion ||
          getActiveConversationId() !== conversationId ||
          isChatRunning(targetChat) ||
          activeState !== 'streaming'
        ) {
          return;
        }
        getTransport(conversationId)?.prepareConversationResume(
          targetChat.messages,
        );
        await targetChat.resumeStream();
      } catch (error) {
        onError(
          error instanceof Error
            ? error
            : new Error('Unable to resume the conversation stream'),
        );
      }
    },
    [
      getActiveConversationId,
      getChat,
      getConversationActiveState,
      getTransport,
      onError,
      onMarkRead,
      refresh,
    ],
  );

  useEffect(() => {
    if (!chatSurfaceOpen || activeConversationId === AI_DRAFT_CONVERSATION_ID) {
      return;
    }
    const targetChat = getChat(activeConversationId);
    if (isChatRunning(targetChat)) return;

    void refresh(activeConversationId, targetChat, { updateRead: true })
      .then(() => {
        if (
          surfaceOpenRef.current &&
          getActiveConversationId() === activeConversationId
        ) {
          onMarkRead(activeConversationId);
        }
      })
      .catch((error: unknown) => {
        onError(
          error instanceof Error
            ? error
            : new Error('Unable to mark the conversation as read'),
        );
      });
  }, [
    activeConversationId,
    chatSurfaceOpen,
    getActiveConversationId,
    getChat,
    onError,
    onMarkRead,
    refresh,
  ]);

  const invalidate = useCallback(() => {
    openVersionRef.current += 1;
  }, []);

  return { invalidate, load, loadingId, refresh };
}

export { NocoBaseAIService } from './nocobase-ai-service.js';
export type {
  AIService,
  CreateAIConversationOptions,
  UpdateToolCallDecisionOptions,
  UpdatedToolCall,
} from './types.js';

import {
  resolveAppUrl,
  type ApiClient,
  type ApiRequestOptions,
} from '@nocobase/app-client';
import type {
  AIChatMessage,
  AIConversation,
  AIEmployee,
  AIModel,
} from '../providers/types.js';
import type { AIService, CreateAIConversationOptions } from './types.js';
import type { UpdateToolCallDecisionOptions } from './types.js';
import {
  getToolCallState,
  getToolProviderMetadata,
  type NocoBaseToolCall,
} from '../providers/stream-event-utils.js';
import { toText } from '../shared/text.js';

const isRecord = (value: unknown): value is Record<string, unknown> =>
  !!value && typeof value === 'object' && !Array.isArray(value);

const parseToolInput = (value: unknown) => {
  if (typeof value !== 'string') return value;
  try {
    return JSON.parse(value) as unknown;
  } catch {
    return value;
  }
};

const toAttachment = (
  value: unknown,
  index: number,
  resolveUrl: (value: string) => string,
) => {
  if (!isRecord(value)) return undefined;
  const filename = value.filename ?? value.name ?? value.title;
  if (typeof filename !== 'string') return undefined;
  return {
    ...value,
    uid: toText(value.id ?? value.uid, `${filename}-${index}`),
    filename,
    status: 'done' as const,
    size: typeof value.size === 'number' ? value.size : undefined,
    mimetype:
      typeof value.mimetype === 'string'
        ? value.mimetype
        : typeof value.type === 'string'
          ? value.type
          : undefined,
    url: typeof value.url === 'string' ? resolveUrl(value.url) : undefined,
    preview:
      typeof value.preview === 'string' ? resolveUrl(value.preview) : undefined,
  };
};

const toHistoryMessage = (
  value: unknown,
  index: number,
  resolveUrl: (value: string) => string,
): AIChatMessage => {
  const message = isRecord(value) ? value : {};
  const content = isRecord(message.content) ? message.content : {};
  const rawServerMessageId = content.messageId ?? message.messageId;
  const serverMessageId =
    typeof rawServerMessageId === 'number' ||
    (typeof rawServerMessageId === 'string' && /^\d+$/.test(rawServerMessageId))
      ? String(rawServerMessageId)
      : undefined;
  const messageId = serverMessageId ?? toText(message.key, `history-${index}`);
  const text =
    typeof content.content === 'string'
      ? content.content
      : typeof message.content === 'string'
        ? message.content
        : '';
  const attachments = Array.isArray(content.attachments)
    ? content.attachments
        .map((attachment, attachmentIndex) =>
          toAttachment(attachment, attachmentIndex, resolveUrl),
        )
        .filter((attachment) => attachment !== undefined)
    : [];
  const parts: AIChatMessage['parts'] = [];
  const reasoning = isRecord(content.reasoning) ? content.reasoning : undefined;
  if (typeof reasoning?.content === 'string' && reasoning.content) {
    parts.push({ type: 'reasoning', text: reasoning.content, state: 'done' });
  }
  if (text) parts.push({ type: 'text', text, state: 'done' });
  const toolCalls = Array.isArray(content.tool_calls)
    ? content.tool_calls
    : Array.isArray(message.toolCalls)
      ? message.toolCalls
      : [];
  for (const rawToolCall of toolCalls) {
    if (!isRecord(rawToolCall)) continue;
    const toolCallId = toText(rawToolCall.id, `tool-${crypto.randomUUID()}`);
    const toolName = toText(rawToolCall.name, 'tool');
    const toolCall = rawToolCall as NocoBaseToolCall;
    const { failed, completed } = getToolCallState(toolCall);
    const callProviderMetadata = getToolProviderMetadata(toolCall);
    parts.push(
      failed
        ? {
            type: 'dynamic-tool',
            toolCallId,
            toolName,
            state: 'output-error',
            input: parseToolInput(rawToolCall.args ?? {}),
            errorText: toText(rawToolCall.content, 'Tool call failed'),
            callProviderMetadata,
          }
        : completed
          ? {
              type: 'dynamic-tool',
              toolCallId,
              toolName,
              state: 'output-available',
              input: parseToolInput(rawToolCall.args ?? {}),
              output: rawToolCall.content,
              callProviderMetadata,
            }
          : {
              type: 'dynamic-tool',
              toolCallId,
              toolName,
              state: 'input-available',
              input: parseToolInput(rawToolCall.args ?? {}),
              callProviderMetadata,
            },
    );
  }
  const subAgentConversations = Array.isArray(content.subAgentConversations)
    ? content.subAgentConversations
    : [];
  for (const [
    conversationIndex,
    rawConversation,
  ] of subAgentConversations.entries()) {
    if (!isRecord(rawConversation)) continue;
    const rawMessages = Array.isArray(rawConversation.messages)
      ? rawConversation.messages
      : [];
    const messages = rawMessages.map((item, messageIndex) =>
      toHistoryMessage(item, messageIndex, resolveUrl),
    );
    const username =
      typeof rawConversation.username === 'string'
        ? rawConversation.username
        : (messages.find((item) => item.metadata?.employeeUsername)?.metadata
            ?.employeeUsername ?? 'sub-agent');
    const sessionId = toText(
      rawConversation.sessionId,
      `sub-agent-history-${index}-${conversationIndex}`,
    );
    parts.push({
      type: 'data-subAgent',
      id: sessionId,
      data: {
        sessionId,
        username,
        status:
          rawConversation.status === 'completed' ? 'completed' : 'pending',
        messages,
      },
    });
  }
  for (const attachment of attachments) {
    if (!attachment.url && !attachment.preview) continue;
    parts.push({
      type: 'file',
      mediaType: attachment.mimetype ?? 'application/octet-stream',
      filename: attachment.filename,
      url: attachment.url ?? attachment.preview ?? '',
    });
  }
  const rawRole = toText(message.role, 'assistant');
  const role =
    rawRole === 'user' || rawRole === 'system' ? rawRole : 'assistant';
  return {
    id: messageId,
    role,
    metadata: {
      ...(serverMessageId ? { serverMessageId } : {}),
      ...(rawRole !== 'user' && rawRole !== 'system'
        ? { employeeUsername: rawRole }
        : {}),
      createdAt:
        typeof message.createdAt === 'string' ? message.createdAt : undefined,
      attachments,
      workContext: Array.isArray(content.workContext)
        ? content.workContext
        : undefined,
    },
    parts,
  };
};

type AIRequestOptions = {
  readonly method?: 'GET' | 'POST' | 'PUT' | 'PATCH' | 'DELETE';
  readonly query?: Readonly<
    Record<string, string | number | boolean | null | undefined>
  >;
  readonly body?: unknown;
  readonly signal?: AbortSignal;
};

/**
 * The path of an AI route under `/api`, each segment encoded. The employees are under `aiEmployees`; conversations,
 * files and models under `aiEmployee`.
 */
function aiPath(...segments: readonly string[]): string {
  return segments.map((segment) => encodeURIComponent(segment)).join('/');
}

function createRequestOptions(
  path: string,
  options: AIRequestOptions,
): ApiRequestOptions {
  const method =
    options.method ?? (options.body === undefined ? 'GET' : 'POST');
  const body = options.body;
  return {
    path,
    method,
    ...(options.query === undefined ? {} : { query: options.query }),
    ...(typeof FormData !== 'undefined' && body instanceof FormData
      ? { body }
      : body === undefined
        ? {}
        : { json: body }),
    ...(options.signal === undefined ? {} : { signal: options.signal }),
  };
}

function resolveResourceUrl(value: string): string {
  if (!value || /^[a-z][a-z\d+.-]*:/i.test(value)) return value;
  return resolveAppUrl(value.replace(/^\/+/, ''));
}

/** Convert a newest-first server history page using the shared chat protocol. */
export function toAIChatHistoryMessages(
  rows: readonly unknown[],
): AIChatMessage[] {
  return [...rows]
    .reverse()
    .filter(
      (value) =>
        !isRecord(value) || (value.role !== 'tool' && value.role !== 'system'),
    )
    .map((value, index) => toHistoryMessage(value, index, resolveResourceUrl));
}

/** The body of a run request: everything but the conversation, which the path names. */
type RunBody = { readonly sessionId?: unknown } & Record<string, unknown>;

function runRequest(body: unknown): {
  sessionId: string;
  body: Record<string, unknown>;
} {
  const { sessionId, ...rest } = (isRecord(body) ? body : {}) as RunBody;
  if (typeof sessionId !== 'string' || !sessionId)
    throw new Error('A conversation is required to run a request.');
  return { sessionId, body: rest };
}

export class NocoBaseAIService implements AIService {
  constructor(private readonly client: ApiClient) {}

  /** Calls an AI route and returns its `data`. */
  private async aiRequest<T>(
    path: string,
    options: AIRequestOptions = {},
  ): Promise<T> {
    const payload = await this.client.request<{ data: T } | undefined>(
      createRequestOptions(path, options),
    );
    return payload?.data as T;
  }

  private aiStream(
    path: string,
    options: AIRequestOptions = {},
  ): Promise<ReadableStream<Uint8Array>> {
    return this.client.stream(createRequestOptions(path, options));
  }

  private runStream(
    verb: 'send' | 'resend' | 'resumeToolCall',
    body: unknown,
    signal?: AbortSignal,
  ): Promise<ReadableStream<Uint8Array>> {
    const request = runRequest(body);
    return this.aiStream(
      aiPath('aiEmployee', 'conversations', request.sessionId, verb),
      { method: 'POST', body: request.body, signal },
    );
  }

  async listEmployees() {
    const employees = await this.aiRequest<AIEmployee[]>(
      aiPath('aiEmployees', 'roster'),
    );
    return employees
      .filter((employee) => employee?.username)
      .map((employee) => ({
        ...employee,
        nickname: employee.nickname ?? employee.username,
        description: employee.description ?? employee.bio,
      }));
  }

  async listModels() {
    const services = await this.aiRequest<
      Array<{
        llmService: string;
        llmServiceTitle: string;
        enabledModels?: Array<{ label: string; value: string }>;
        supportWebSearch?: boolean;
        webSearchModels?: string[];
        isToolConflict?: boolean;
      }>
    >(aiPath('aiEmployee', 'models'));
    return services.flatMap((service) =>
      (service.enabledModels ?? []).map<AIModel>((model) => ({
        value: model.value,
        label: model.label,
        llmService: service.llmService,
        llmServiceTitle: service.llmServiceTitle,
        supportWebSearch:
          service.supportWebSearch === true &&
          (!service.webSearchModels?.length ||
            service.webSearchModels.includes(model.value)),
        isToolConflict: service.isToolConflict,
      })),
    );
  }

  async updateEmployeeUserPrompt(username: string, prompt: string) {
    await this.aiRequest(aiPath('aiEmployees', username, 'userPrompt'), {
      method: 'PUT',
      body: { prompt },
    });
  }

  async listConversations(keyword = '') {
    const normalizedKeyword = keyword.trim();
    const rows = await this.aiRequest<unknown[]>(
      aiPath('aiEmployee', 'conversations'),
      { query: { q: normalizedKeyword || undefined } },
    );
    return (Array.isArray(rows) ? rows : []).flatMap<AIConversation>(
      (value) => {
        if (!isRecord(value) || typeof value.sessionId !== 'string') return [];
        const employee = isRecord(value.aiEmployee)
          ? value.aiEmployee
          : undefined;
        const options = isRecord(value.options) ? value.options : undefined;
        const modelSettings = isRecord(options?.modelSettings)
          ? options.modelSettings
          : undefined;
        return [
          {
            id: value.sessionId,
            title:
              typeof value.title === 'string' && value.title
                ? value.title
                : 'New conversation',
            employeeUsername: toText(
              employee?.username ?? value.aiEmployeeUsername,
              '',
            ),
            updatedAt:
              typeof value.updatedAt === 'string'
                ? value.updatedAt
                : new Date().toISOString(),
            unread: value.read === false,
            model:
              typeof modelSettings?.model === 'string'
                ? {
                    llmService:
                      typeof modelSettings.llmService === 'string'
                        ? modelSettings.llmService
                        : undefined,
                    model: modelSettings.model,
                  }
                : undefined,
          },
        ];
      },
    );
  }

  async getConversationMessages(
    sessionId: string,
    options: { updateRead?: boolean } = {},
  ) {
    // The chat shows a conversation's recent history at once: one page of the largest size the route allows.
    const rows = await this.aiRequest<unknown[]>(
      aiPath('aiEmployee', 'conversations', sessionId, 'messages'),
      { query: { pageSize: 200 } },
    );
    if (options.updateRead === true) {
      await this.aiRequest(
        aiPath('aiEmployee', 'conversations', sessionId, 'markRead'),
        { method: 'POST' },
      );
    }
    return toAIChatHistoryMessages(Array.isArray(rows) ? rows : []);
  }

  async getConversationActiveState(sessionId: string) {
    const conversation = await this.aiRequest<{
      llmActiveState?: unknown;
    }>(aiPath('aiEmployee', 'conversations', sessionId));
    const state = conversation?.llmActiveState;
    return state === 'idle' || state === 'streaming' || state === 'invoking'
      ? state
      : undefined;
  }

  async updateConversationTitle(sessionId: string, title: string) {
    await this.aiRequest(aiPath('aiEmployee', 'conversations', sessionId), {
      method: 'PATCH',
      body: { title },
    });
  }

  async destroyConversation(sessionId: string) {
    await this.aiRequest(aiPath('aiEmployee', 'conversations', sessionId), {
      method: 'DELETE',
    });
  }

  async uploadFile(file: File, signal?: AbortSignal) {
    const formData = new FormData();
    formData.append('file', file);
    const response = await this.aiRequest<Record<string, unknown>>(
      aiPath('aiEmployee', 'files'),
      { body: formData, signal },
    );
    return {
      ...response,
      ...(typeof response.url === 'string'
        ? { url: resolveResourceUrl(response.url) }
        : {}),
      ...(typeof response.preview === 'string'
        ? { preview: resolveResourceUrl(response.preview) }
        : {}),
    };
  }

  async createConversation(options: CreateAIConversationOptions) {
    const conversation = await this.aiRequest<{ sessionId: string }>(
      aiPath('aiEmployee', 'conversations'),
      {
        method: 'POST',
        body: {
          aiEmployee: { username: options.employee.username },
          systemMessage: options.systemMessage,
          skillSettings: options.skillSettings,
          modelSettings: {
            llmService: options.model.llmService,
            model: options.model.value,
          },
        },
      },
    );
    return conversation.sessionId;
  }

  sendMessagesStream(body: unknown, signal?: AbortSignal) {
    return this.runStream('send', body, signal);
  }

  resendMessagesStream(body: unknown, signal?: AbortSignal) {
    return this.runStream('resend', body, signal);
  }

  async updateToolCallDecision(options: UpdateToolCallDecisionOptions) {
    const result = await this.aiRequest<{
      updated: number;
      toolCalls: Array<{
        id: string;
        name: string;
        invokeStatus?: string;
        status?: string;
        auto?: boolean;
        execution?: string;
        willInterrupt?: boolean;
        args?: unknown;
      }>;
    }>(
      aiPath(
        'aiEmployee',
        'conversations',
        options.sessionId,
        'messages',
        options.messageId,
        'toolCalls',
        options.toolCallId,
        'userDecision',
      ),
      { method: 'PUT', body: options.userDecision },
    );
    return {
      ...result,
      toolCalls: result.toolCalls.map((toolCall) => ({
        ...toolCall,
        args: parseToolInput(toolCall.args),
      })),
    };
  }

  resumeToolCallStream(body: unknown, signal?: AbortSignal) {
    return this.runStream('resumeToolCall', body, signal);
  }

  resumeConversationStream(sessionId: string, signal?: AbortSignal) {
    return this.aiStream(
      aiPath('aiEmployee', 'conversations', sessionId, 'resumeStream'),
      { method: 'POST', signal },
    );
  }
}

